async fn project_decision_add_handler(
    TenantExtractor(tenant): TenantExtractor,
    AuditPrincipal(principal): AuditPrincipal,
    Json(body): Json<ProjectDecisionAddBody>,
) -> Result<Json<ProjectDecisionAddResponse>, ApiError> {
    let project = body.project.normalized().map_err(ApiError::bad_request)?;
    let decision = body.decision.trim();
    if decision.is_empty() {
        return Err(ApiError::bad_request("decision must not be empty"));
    }
    let now = chrono::Utc::now().timestamp_millis();
    let content = project_decision_content(&project, decision);
    let source_id = project_decision_source_id(&project.id, now);
    let embedding = tenant
        .embedder()
        .embed(&content)
        .await
        .map_err(ApiError::from)?;
    let episode = Episode {
        memory_id: MemoryId::new(),
        ts_ms: now,
        source_type: PROJECT_DECISION_SOURCE_TYPE.to_string(),
        source_id: Some(source_id.clone()),
        content: content.clone(),
        encoding_context: project_decision_encoding_context(&project),
        provenance: None,
        confidence: Confidence::new(0.95).expect("0.95 is in [0.0, 1.0]"),
        strength: 0.7,
        salience: 0.8,
        tier: Tier::Hot,
    };
    let memory_id = tenant
        .write()
        .remember_as(principal, episode, embedding)
        .await
        .map_err(ApiError::from)?;
    Ok(Json(ProjectDecisionAddResponse {
        command: "project decisions",
        action: "add",
        project,
        memory_id: memory_id.to_string(),
        source_type: PROJECT_DECISION_SOURCE_TYPE,
        source_id,
        content,
    }))
}

async fn project_decision_search_handler(
    TenantExtractor(tenant): TenantExtractor,
    AuditPrincipal(principal): AuditPrincipal,
    Json(body): Json<ProjectDecisionSearchBody>,
) -> Result<Json<ProjectDecisionSearchResponse>, ApiError> {
    let project = body.project.normalized().map_err(ApiError::bad_request)?;
    let query = body.query.trim().to_string();
    if query.is_empty() {
        return Err(ApiError::bad_request("query must not be empty"));
    }
    let limit = project_limit(body.limit, 5);
    let scoped_query = format!(
        "Project decision for {} (id: {}): {}",
        project.name, project.id, query
    );
    let result = solo_query::run_recall(tenant.as_ref(), principal, &scoped_query, 100)
        .await
        .map_err(ApiError::from)?;
    let rowids = result.hits.iter().map(|hit| hit.rowid).collect::<Vec<_>>();
    let metadata = fetch_project_decision_hit_metadata(tenant.read(), &rowids).await?;
    let hits = result
        .hits
        .into_iter()
        .filter(|hit| project_decision_hit_matches_project(hit, metadata.get(&hit.rowid), &project))
        .take(limit)
        .collect();
    Ok(Json(ProjectDecisionSearchResponse {
        command: "project decisions",
        action: "query",
        project,
        query,
        limit,
        hits,
    }))
}

async fn project_policy_handler(
    Json(body): Json<ProjectPolicyBody>,
) -> Result<Json<ProjectPolicyResponse>, ApiError> {
    let project = body.project.normalized().map_err(ApiError::bad_request)?;
    let policy = render_project_policy(body.client, &project);
    Ok(Json(ProjectPolicyResponse {
        command: "project policy",
        client: body.client.as_str(),
        project,
        policy,
    }))
}

fn project_limit(limit: Option<usize>, default: usize) -> usize {
    limit.unwrap_or(default).clamp(1, 100)
}

fn project_subject(project: &ProjectDescriptor, subject: Option<&str>) -> String {
    subject
        .map(str::trim)
        .filter(|subject| !subject.is_empty())
        .unwrap_or(&project.name)
        .to_string()
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProjectDecisionHitMetadata {
    source_id: Option<String>,
    encoding_context_json: String,
}

async fn fetch_project_decision_hit_metadata(
    pool: &solo_storage::ReaderPool,
    rowids: &[i64],
) -> Result<std::collections::HashMap<i64, ProjectDecisionHitMetadata>, ApiError> {
    if rowids.is_empty() {
        return Ok(std::collections::HashMap::new());
    }
    let rowids = rowids.to_vec();
    let rows = pool
        .interact(move |conn| {
            let placeholders = std::iter::repeat("?")
                .take(rowids.len())
                .collect::<Vec<_>>()
                .join(",");
            let sql = format!(
                "SELECT rowid, source_id, encoding_context_json
                   FROM episodes
                  WHERE rowid IN ({placeholders})"
            );
            let mut stmt = conn.prepare(&sql)?;
            stmt.query_map(rusqlite::params_from_iter(rowids.iter()), |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    ProjectDecisionHitMetadata {
                        source_id: row.get(1)?,
                        encoding_context_json: row.get(2)?,
                    },
                ))
            })?
            .collect::<rusqlite::Result<Vec<_>>>()
        })
        .await
        .map_err(ApiError::from)?;
    Ok(rows.into_iter().collect())
}

fn project_decision_hit_matches_project(
    hit: &solo_query::RecallHit,
    metadata: Option<&ProjectDecisionHitMetadata>,
    project: &ProjectDescriptor,
) -> bool {
    if hit.source_type != PROJECT_DECISION_SOURCE_TYPE {
        return false;
    }
    let source_id = metadata.and_then(|metadata| metadata.source_id.as_deref());
    let encoding_context_json = metadata
        .map(|metadata| metadata.encoding_context_json.as_str())
        .unwrap_or("{}");
    project_decision_scope_matches(source_id, encoding_context_json, &hit.content, &project.id)
}

