#[derive(Debug, Deserialize)]
struct MemoryQualityAuditQuery {
    #[serde(default)]
    low_confidence_below: Option<f32>,
    #[serde(default)]
    low_coherence_below: Option<f32>,
    #[serde(default)]
    long_literal_chars: Option<usize>,
    #[serde(default)]
    sample_limit: Option<usize>,
}

fn memory_quality_config_from_query(
    q: MemoryQualityAuditQuery,
) -> Result<solo_query::MemoryQualityAuditConfig, ApiError> {
    let mut config = solo_query::MemoryQualityAuditConfig::default();
    if let Some(value) = q.low_confidence_below {
        if !(0.0..=1.0).contains(&value) {
            return Err(ApiError::bad_request(
                "low_confidence_below must be between 0.0 and 1.0",
            ));
        }
        config.low_confidence_below = value;
    }
    if let Some(value) = q.low_coherence_below {
        if !(0.0..=1.0).contains(&value) {
            return Err(ApiError::bad_request(
                "low_coherence_below must be between 0.0 and 1.0",
            ));
        }
        config.low_coherence_below = value;
    }
    if let Some(value) = q.long_literal_chars {
        config.long_literal_chars = value;
    }
    if let Some(value) = q.sample_limit {
        config.sample_limit = value;
    }
    Ok(config)
}

