#[derive(Debug, Serialize)]
struct MemoryQualityReviewItem {
    review_id: String,
    claim_id: Option<String>,
    triple_id: Option<String>,
    cluster_id: Option<String>,
    source_episode_id: Option<i64>,
    subject_id: String,
    predicate: String,
    object_id: String,
    object_kind: String,
    confidence: f32,
    reason_code: String,
    reason: String,
    status: String,
    claim_status: Option<String>,
    quality_score: Option<f32>,
    claim_reason_codes: Vec<String>,
    created_at_ms: i64,
    evidence_preview: Option<String>,
}

impl From<MemoryQualityReviewUpdateReport> for MemoryQualityReviewItem {
    fn from(report: MemoryQualityReviewUpdateReport) -> Self {
        Self {
            review_id: report.review_id,
            claim_id: report.claim_id,
            triple_id: report.triple_id,
            cluster_id: report.cluster_id,
            source_episode_id: report.source_episode_id,
            subject_id: report.subject_id,
            predicate: report.predicate,
            object_id: report.object_id,
            object_kind: report.object_kind,
            confidence: report.confidence,
            reason_code: report.reason_code,
            reason: report.reason,
            status: report.status,
            claim_status: report.claim_status,
            quality_score: report.quality_score,
            claim_reason_codes: report.claim_reason_codes,
            created_at_ms: report.created_at_ms,
            evidence_preview: report.evidence_preview,
        }
    }
}

fn parse_claim_reason_codes(raw: Option<String>) -> Vec<String> {
    raw.and_then(|s| serde_json::from_str::<Vec<String>>(&s).ok())
        .unwrap_or_default()
}

#[derive(Debug, Serialize)]
struct MemoryQualityReviewsResponse {
    items: Vec<MemoryQualityReviewItem>,
}

#[derive(Debug, Deserialize)]
struct MemoryQualityReviewUpdateRequest {
    status: String,
    #[serde(default)]
    note: Option<String>,
    #[serde(default)]
    rewrite: Option<MemoryQualityReviewRewriteFact>,
    #[serde(default)]
    rewrites: Vec<MemoryQualityReviewRewriteFact>,
}

#[derive(Debug, Deserialize)]
struct MemoryQualityReviewRewriteFact {
    subject_id: String,
    predicate: String,
    object_id: String,
    object_kind: String,
    #[serde(default)]
    confidence: Option<f32>,
}

fn validate_memory_quality_rewrite_fact(
    fact: &MemoryQualityReviewRewriteFact,
) -> Result<(), ApiError> {
    let object_kind = fact.object_kind.trim();
    if !matches!(object_kind, "entity" | "literal") {
        return Err(ApiError::bad_request(
            "rewrite object_kind must be entity or literal",
        ));
    }
    if fact.subject_id.trim().is_empty()
        || fact.predicate.trim().is_empty()
        || fact.object_id.trim().is_empty()
    {
        return Err(ApiError::bad_request(
            "rewrite subject_id, predicate, and object_id must not be empty",
        ));
    }
    if let Some(confidence) = fact.confidence {
        if !(0.0..=1.0).contains(&confidence) {
            return Err(ApiError::bad_request(
                "rewrite confidence must be between 0.0 and 1.0",
            ));
        }
    }
    Ok(())
}

async fn memory_quality_reviews_handler(
    TenantExtractor(tenant): TenantExtractor,
    Query(q): Query<MemoryQualityReviewsQuery>,
) -> Result<Json<MemoryQualityReviewsResponse>, ApiError> {
    let claim_status = q.claim_status.unwrap_or_else(|| "all".to_string());
    let status = q.status.unwrap_or_else(|| {
        if claim_status == "all" {
            "needs_review".to_string()
        } else {
            "all".to_string()
        }
    });
    if !matches!(
        status.as_str(),
        "needs_review" | "approved" | "dismissed" | "rewritten" | "all"
    ) {
        return Err(ApiError::bad_request(
            "status must be needs_review, approved, dismissed, rewritten, or all",
        ));
    }
    if !matches!(
        claim_status.as_str(),
        "candidate" | "active" | "needs_review" | "rejected" | "quarantined" | "superseded" | "all"
    ) {
        return Err(ApiError::bad_request(
            "claim_status must be candidate, active, needs_review, rejected, quarantined, superseded, or all",
        ));
    }
    let limit = q.limit.clamp(1, 200) as i64;
    let items = tenant
        .read()
        .interact(move |conn| {
            let mut sql = String::from(
                "SELECT tr.review_id, mc.claim_id, tr.triple_id, tr.cluster_id, tr.source_episode_id,
                        tr.subject_id, tr.predicate, tr.object_id, tr.object_kind,
                        tr.confidence, tr.reason_code, tr.reason, tr.status, tr.created_at_ms,
                        mc.status AS claim_status, mc.quality_score, mc.reason_codes_json,
                        substr(e.content, 1, 240) AS evidence_preview
                   FROM triple_reviews tr
                   LEFT JOIN episodes e ON e.rowid = tr.source_episode_id
                   LEFT JOIN memory_claims mc
                     ON mc.claim_id = COALESCE((
                        SELECT mc2.claim_id
                          FROM memory_claims mc2
                         WHERE mc2.review_id = tr.review_id
                         ORDER BY mc2.updated_at_ms DESC,
                                  mc2.claim_id
                         LIMIT 1
                     ), (
                        SELECT mc3.claim_id
                          FROM memory_claims mc3
                         WHERE mc3.candidate_fingerprint = tr.candidate_fingerprint
                         LIMIT 1
                     ))",
            );
            let mut params: Vec<rusqlite::types::Value> = Vec::new();
            let mut where_clauses: Vec<&str> = Vec::new();
            if status != "all" {
                where_clauses.push("tr.status = ?");
                params.push(status.into());
            }
            if claim_status != "all" {
                where_clauses.push("mc.status = ?");
                params.push(claim_status.into());
            }
            if !where_clauses.is_empty() {
                sql.push_str(" WHERE ");
                sql.push_str(&where_clauses.join(" AND "));
            }
            sql.push_str(" ORDER BY tr.created_at_ms DESC LIMIT ?");
            params.push(limit.into());
            let mut stmt = conn.prepare(&sql)?;
            stmt.query_map(rusqlite::params_from_iter(params), |r| {
                let reason_codes_json: Option<String> = r.get(16)?;
                Ok(MemoryQualityReviewItem {
                    review_id: r.get(0)?,
                    claim_id: r.get(1)?,
                    triple_id: r.get(2)?,
                    cluster_id: r.get(3)?,
                    source_episode_id: r.get(4)?,
                    subject_id: r.get(5)?,
                    predicate: r.get(6)?,
                    object_id: r.get(7)?,
                    object_kind: r.get(8)?,
                    confidence: r.get(9)?,
                    reason_code: r.get(10)?,
                    reason: r.get(11)?,
                    status: r.get(12)?,
                    created_at_ms: r.get(13)?,
                    claim_status: r.get(14)?,
                    quality_score: r.get(15)?,
                    claim_reason_codes: parse_claim_reason_codes(reason_codes_json),
                    evidence_preview: r.get(17)?,
                })
            })?
            .collect::<rusqlite::Result<Vec<_>>>()
        })
        .await
        .map_err(ApiError::from)?;
    Ok(Json(MemoryQualityReviewsResponse { items }))
}

async fn memory_quality_review_update_handler(
    TenantExtractor(tenant): TenantExtractor,
    AuditPrincipal(principal): AuditPrincipal,
    Path(review_id): Path<String>,
    Json(body): Json<MemoryQualityReviewUpdateRequest>,
) -> Result<Json<MemoryQualityReviewItem>, ApiError> {
    let review_id = review_id.trim().to_string();
    if review_id.is_empty() {
        return Err(ApiError::bad_request("review_id must not be empty"));
    }
    let status = MemoryQualityReviewStatus::from_str(body.status.trim()).map_err(ApiError::from)?;
    let note = body
        .note
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty());
    let mut rewrites = body.rewrites;
    if let Some(rewrite) = body.rewrite {
        rewrites.push(rewrite);
    }
    for rewrite in &rewrites {
        validate_memory_quality_rewrite_fact(rewrite)?;
    }
    let update = MemoryQualityReviewUpdate {
        review_id,
        status,
        note,
        rewrites: rewrites
            .into_iter()
            .map(|rewrite| MemoryQualityReviewRewrite {
                subject_id: rewrite.subject_id,
                predicate: rewrite.predicate,
                object_id: rewrite.object_id,
                object_kind: rewrite.object_kind,
                confidence: rewrite.confidence,
            })
            .collect(),
    };
    let item = tenant
        .write()
        .update_memory_quality_review_as(principal, update)
        .await
        .map_err(ApiError::from)?;
    Ok(Json(item.into()))
}

