async fn asset_download_handler(
    TenantExtractor(tenant): TenantExtractor,
    AuditPrincipal(principal): AuditPrincipal,
    Path(asset_id): Path<String>,
) -> Result<Response, ApiError> {
    let asset_id = AssetId::from_str(&asset_id)
        .map_err(|e| ApiError::bad_request(format!("invalid asset_id: {e}")))?;
    let target = solo_query::download_asset(
        tenant.read(),
        tenant.audit(),
        principal.clone(),
        tenant.snapshot_dir(),
        &asset_id,
    )
    .await
    .map_err(ApiError::from)?;
    let audit_target = Some(asset_id.to_string());
    let stored_bytes = match tokio::fs::read(&target.path).await {
        Ok(bytes) => bytes,
        Err(e) => {
            let message = format!("read asset blob {}: {e}", target.path.display());
            tenant.audit().emit_error(
                principal.clone(),
                AuditOperation::MemoryDownloadAsset,
                audit_target.clone(),
                &message,
            );
            return Err(ApiError::internal(message));
        }
    };
    let bytes = match solo_storage::decode_asset_blob(
        tenant.key(),
        &target.asset.encryption_alg,
        target.asset.encryption_nonce.as_deref(),
        &target.asset.sha256,
        target.asset.size_bytes,
        &stored_bytes,
    ) {
        Ok(bytes) => bytes,
        Err(e) => {
            tenant.audit().emit_error(
                principal.clone(),
                AuditOperation::MemoryDownloadAsset,
                audit_target.clone(),
                &e,
            );
            return Err(ApiError::from(e));
        }
    };
    if bytes.len() as u64 != target.asset.size_bytes {
        let message = format!(
            "asset blob plaintext size mismatch while downloading {asset_id}: expected {}, got {}",
            target.asset.size_bytes,
            bytes.len()
        );
        tenant.audit().emit_error(
            principal.clone(),
            AuditOperation::MemoryDownloadAsset,
            audit_target.clone(),
            &message,
        );
        return Err(ApiError::internal(message));
    }

    let mut response = axum::body::Body::from(bytes).into_response();
    let headers = response.headers_mut();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        header_value_or_octet_stream(&target.asset.mime_type),
    );
    headers.insert(
        axum::http::header::CONTENT_LENGTH,
        HeaderValue::from_str(&target.asset.size_bytes.to_string())
            .map_err(|e| ApiError::internal(format!("invalid asset content-length header: {e}")))?,
    );
    headers.insert(
        axum::http::header::CONTENT_DISPOSITION,
        HeaderValue::from_str(&content_disposition_attachment(
            target.asset.filename.as_deref(),
        ))
        .map_err(|e| ApiError::internal(format!("invalid content-disposition header: {e}")))?,
    );
    headers.insert(
        axum::http::header::ETAG,
        HeaderValue::from_str(&format!("\"{}\"", target.asset.sha256))
            .map_err(|e| ApiError::internal(format!("invalid etag header: {e}")))?,
    );
    tenant.audit().emit_ok(
        principal,
        AuditOperation::MemoryDownloadAsset,
        Some(asset_id.to_string()),
    );
    Ok(response)
}

fn header_value_or_octet_stream(value: &str) -> HeaderValue {
    HeaderValue::from_str(value.trim())
        .unwrap_or_else(|_| HeaderValue::from_static("application/octet-stream"))
}

fn content_disposition_attachment(filename: Option<&str>) -> String {
    let filename = filename
        .map(sanitize_header_filename)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "asset.bin".to_string());
    format!("attachment; filename=\"{filename}\"")
}

fn sanitize_header_filename(value: &str) -> String {
    value
        .chars()
        .map(|ch| match ch {
            '"' | '\\' | '/' | '\0'..='\u{1f}' | '\u{7f}' => '_',
            ch if ch.is_ascii() => ch,
            _ => '_',
        })
        .collect()
}

fn parse_upload_offset_header(headers: &HeaderMap) -> Result<u64, ApiError> {
    let value = headers
        .get(crate::document_upload::UPLOAD_OFFSET_HEADER)
        .ok_or_else(|| {
            ApiError::bad_request(format!(
                "{} header is required",
                crate::document_upload::UPLOAD_OFFSET_HEADER
            ))
        })?
        .to_str()
        .map_err(|e| {
            ApiError::bad_request(format!(
                "{} header must be ASCII: {e}",
                crate::document_upload::UPLOAD_OFFSET_HEADER
            ))
        })?;
    value.parse::<u64>().map_err(|e| {
        ApiError::bad_request(format!(
            "{} header must be an integer byte offset: {e}",
            crate::document_upload::UPLOAD_OFFSET_HEADER
        ))
    })
}

fn parse_optional_upload_length_header(headers: &HeaderMap) -> Result<Option<u64>, ApiError> {
    let Some(value) = headers.get(crate::document_upload::UPLOAD_LENGTH_HEADER) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|e| {
        ApiError::bad_request(format!(
            "{} header must be ASCII: {e}",
            crate::document_upload::UPLOAD_LENGTH_HEADER
        ))
    })?;
    value.parse::<u64>().map(Some).map_err(|e| {
        ApiError::bad_request(format!(
            "{} header must be an integer byte length: {e}",
            crate::document_upload::UPLOAD_LENGTH_HEADER
        ))
    })
}

fn upload_offset_response(
    status: StatusCode,
    upload: &crate::document_upload::UploadStatusResponse,
) -> Result<Response, ApiError> {
    let mut response = status.into_response();
    response.headers_mut().insert(
        axum::http::HeaderName::from_static(crate::document_upload::UPLOAD_OFFSET_HEADER),
        HeaderValue::from_str(&upload.next_offset.to_string())
            .map_err(|e| ApiError::internal(format!("invalid upload offset header: {e}")))?,
    );
    response.headers_mut().insert(
        axum::http::HeaderName::from_static(crate::document_upload::UPLOAD_LENGTH_HEADER),
        HeaderValue::from_str(&upload.size_bytes.to_string())
            .map_err(|e| ApiError::internal(format!("invalid upload length header: {e}")))?,
    );
    response.headers_mut().insert(
        axum::http::HeaderName::from_static(crate::document_upload::UPLOAD_STATUS_HEADER),
        HeaderValue::from_str(match upload.status {
            crate::document_upload::UploadStatus::Open => "open",
            crate::document_upload::UploadStatus::Busy => "busy",
            crate::document_upload::UploadStatus::Committed => "committed",
            crate::document_upload::UploadStatus::Ingested => "ingested",
            crate::document_upload::UploadStatus::Expired => "expired",
            crate::document_upload::UploadStatus::Aborted => "aborted",
        })
        .map_err(|e| ApiError::internal(format!("invalid upload status header: {e}")))?,
    );
    Ok(response)
}

const DEFAULT_NATIVE_IMPORT_MAX_FILES: usize = 500;
const MAX_NATIVE_IMPORT_MAX_FILES: usize = 5_000;
const MAX_NATIVE_IMPORT_VISITED_ENTRIES: usize = 20_000;

#[derive(Debug, Deserialize)]
struct ImportDocumentsBody {
    /// Server-side file or directory path readable by the Solo process.
    path: String,
    /// Import source. Defaults to native document scanning. Schema-aware
    /// sources parse app exports into materialized Markdown before ingest.
    #[serde(default)]
    source: Option<String>,
    /// Optional ChatGPT/Claude id or title filters.
    #[serde(default)]
    conversations: Vec<String>,
    /// When true, only scan and report candidates.
    #[serde(default)]
    dry_run: bool,
    /// Recursively scan directories. Defaults to true.
    #[serde(default = "default_true")]
    recursive: bool,
    /// Safety cap for directory scans/imports.
    #[serde(default = "default_native_import_max_files")]
    max_files: usize,
    /// If true, copy each successfully ingested original file into Solo's
    /// persistent asset store and link it to the document.
    #[serde(default)]
    store_original_file: bool,
}

#[derive(Debug, Serialize)]
struct NativeImportFile {
    path: String,
    bytes: u64,
    #[serde(skip_serializing)]
    path_buf: std::path::PathBuf,
}

#[derive(Debug, Serialize)]
struct NativeImportResult {
    path: String,
    bytes: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    doc_id: Option<String>,
    chunks_persisted: u32,
    bytes_ingested: u64,
    deduped: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    asset: Option<solo_storage::StoredAssetReport>,
    #[serde(skip_serializing_if = "Option::is_none")]
    document_asset_link: Option<solo_storage::DocumentAssetLinkReport>,
    #[serde(skip_serializing_if = "Option::is_none")]
    asset_error: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error: Option<String>,
}

#[derive(Debug, Serialize)]
struct NativeImportResponse {
    path: String,
    source: String,
    source_label: String,
    dry_run: bool,
    recursive: bool,
    truncated: bool,
    total_files: usize,
    total_bytes: u64,
    store_original_file: bool,
    imported: u32,
    deduped: u32,
    failed: u32,
    chunks_persisted: u32,
    assets_retained: u32,
    assets_deduped: u32,
    asset_links: u32,
    asset_failed: u32,
    files: Vec<NativeImportFile>,
    results: Vec<NativeImportResult>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ImportDocumentsSource {
    NativeAll,
    NativeMarkdown,
    NativeText,
    NativeMarkdownText,
    NativeJson,
    Schema(solo_storage::SchemaImportSource),
}

impl ImportDocumentsSource {
    fn response_source(self) -> &'static str {
        match self {
            Self::NativeAll => "native",
            Self::NativeMarkdown => "markdown",
            Self::NativeText => "text",
            Self::NativeMarkdownText => "markdown_text",
            Self::NativeJson => "json",
            Self::Schema(source) => source.command_name(),
        }
    }

    fn response_label(self) -> &'static str {
        match self {
            Self::NativeAll => "Documents",
            Self::NativeMarkdown => "Markdown",
            Self::NativeText => "Text",
            Self::NativeMarkdownText => "Markdown/Text",
            Self::NativeJson => "JSON",
            Self::Schema(source) => source.display_name(),
        }
    }
}

#[derive(Debug)]
struct NativeImportIngestSummary {
    imported: u32,
    deduped: u32,
    failed: u32,
    chunks_persisted: u32,
    assets_retained: u32,
    assets_deduped: u32,
    asset_links: u32,
    asset_failed: u32,
    results: Vec<NativeImportResult>,
}

fn default_true() -> bool {
    true
}

fn default_native_import_max_files() -> usize {
    DEFAULT_NATIVE_IMPORT_MAX_FILES
}

fn native_import_home_dir() -> Option<std::path::PathBuf> {
    if cfg!(windows) {
        std::env::var_os("USERPROFILE")
            .map(std::path::PathBuf::from)
            .or_else(|| {
                let drive = std::env::var_os("HOMEDRIVE")?;
                let path = std::env::var_os("HOMEPATH")?;
                let mut home = std::path::PathBuf::from(drive);
                home.push(path);
                Some(home)
            })
    } else {
        std::env::var_os("HOME").map(std::path::PathBuf::from)
    }
}

fn expand_home_prefix(raw_path: &str, home_dir: Option<&std::path::Path>) -> std::path::PathBuf {
    let Some(home) = home_dir else {
        return std::path::PathBuf::from(raw_path);
    };
    if raw_path == "~" {
        return home.to_path_buf();
    }
    if let Some(rest) = raw_path
        .strip_prefix("~/")
        .or_else(|| raw_path.strip_prefix("~\\"))
    {
        return home.join(rest);
    }
    std::path::PathBuf::from(raw_path)
}

fn parse_import_documents_source(raw: Option<&str>) -> Result<ImportDocumentsSource, ApiError> {
    let Some(raw) = raw else {
        return Ok(ImportDocumentsSource::NativeAll);
    };
    match raw.trim().to_ascii_lowercase().as_str() {
        "" | "native" | "documents" => Ok(ImportDocumentsSource::NativeAll),
        "markdown" | "md" => Ok(ImportDocumentsSource::NativeMarkdown),
        "text" | "txt" => Ok(ImportDocumentsSource::NativeText),
        "markdown_text" | "markdown-text" | "markdown/text" | "markdown+text" => {
            Ok(ImportDocumentsSource::NativeMarkdownText)
        }
        "json" => Ok(ImportDocumentsSource::NativeJson),
        "chatgpt" | "chat-gpt" => Ok(ImportDocumentsSource::Schema(
            solo_storage::SchemaImportSource::ChatGpt,
        )),
        "claude" => Ok(ImportDocumentsSource::Schema(
            solo_storage::SchemaImportSource::Claude,
        )),
        "bookmarks" | "bookmark" => Ok(ImportDocumentsSource::Schema(
            solo_storage::SchemaImportSource::Bookmarks,
        )),
        other => Err(ApiError::bad_request(format!(
            "source must be native, markdown, text, markdown_text, json, chatgpt, claude, or bookmarks; got {other}"
        ))),
    }
}

fn native_import_allowed_extensions(
    configured: &[String],
    source: ImportDocumentsSource,
) -> Vec<String> {
    let wanted: Option<&[&str]> = match source {
        ImportDocumentsSource::NativeAll => None,
        ImportDocumentsSource::NativeMarkdown => Some(&["md", "markdown"]),
        ImportDocumentsSource::NativeText => Some(&["txt"]),
        ImportDocumentsSource::NativeMarkdownText => Some(&["md", "markdown", "txt"]),
        ImportDocumentsSource::NativeJson => Some(&["json", "jsonl", "ndjson"]),
        ImportDocumentsSource::Schema(_) => Some(&[]),
    };

    let mut out = Vec::new();
    for ext in configured {
        let normalized = ext.trim_start_matches('.').to_ascii_lowercase();
        if normalized.is_empty() {
            continue;
        }
        if wanted.is_none_or(|wanted| wanted.contains(&normalized.as_str()))
            && !out.contains(&normalized)
        {
            out.push(normalized);
        }
    }
    out.sort();
    out
}

async fn import_documents_handler(
    State(state): State<SoloHttpState>,
    TenantExtractor(tenant): TenantExtractor,
    AuditPrincipal(principal): AuditPrincipal,
    Json(body): Json<ImportDocumentsBody>,
) -> Result<Json<NativeImportResponse>, ApiError> {
    let raw_path = body.path.trim();
    if raw_path.is_empty() {
        return Err(ApiError::bad_request("path must not be empty"));
    }
    if body.max_files == 0 {
        return Err(ApiError::bad_request("max_files must be > 0"));
    }
    if body.max_files > MAX_NATIVE_IMPORT_MAX_FILES {
        return Err(ApiError::bad_request(format!(
            "max_files must be <= {MAX_NATIVE_IMPORT_MAX_FILES}"
        )));
    }
    let import_source = parse_import_documents_source(body.source.as_deref())?;

    let requested_path = expand_home_prefix(raw_path, native_import_home_dir().as_deref());
    let checked_path = state
        .workspace_file_access
        .check_path(&requested_path)
        .map_err(ApiError::from)?;
    let response_path = requested_path.display().to_string();
    let import_path = if state.workspace_file_access.is_restricted() {
        checked_path
    } else {
        requested_path
    };
    if let ImportDocumentsSource::Schema(schema_source) = import_source {
        return import_schema_documents(
            state.registry.data_dir().to_path_buf(),
            tenant,
            principal,
            import_path,
            response_path,
            schema_source,
            body.conversations,
            body.dry_run,
            body.max_files,
            body.store_original_file,
        )
        .await;
    }

    let scan_path = import_path.clone();
    let allowed_extensions = native_import_allowed_extensions(
        &tenant.config().documents.allowed_extensions,
        import_source,
    );
    let recursive = body.recursive;
    let max_files = body.max_files;
    let (files, truncated) = tokio::task::spawn_blocking(move || {
        collect_native_import_files(&scan_path, recursive, &allowed_extensions, max_files)
    })
    .await
    .map_err(|e| ApiError::internal(format!("native import scan task failed: {e}")))??;
    let total_bytes = files.iter().map(|file| file.bytes).sum();

    if body.dry_run {
        return Ok(Json(NativeImportResponse {
            path: response_path,
            source: import_source.response_source().to_string(),
            source_label: import_source.response_label().to_string(),
            dry_run: true,
            recursive: body.recursive,
            truncated,
            total_files: files.len(),
            total_bytes,
            store_original_file: body.store_original_file,
            imported: 0,
            deduped: 0,
            failed: 0,
            chunks_persisted: 0,
            assets_retained: 0,
            assets_deduped: 0,
            asset_links: 0,
            asset_failed: 0,
            files,
            results: Vec::new(),
        }));
    }

    let chunk_config = chunk_config_from_document_config(&tenant.config().documents)?;
    let ingest = ingest_import_files(
        tenant.as_ref(),
        principal,
        &files,
        chunk_config,
        body.store_original_file,
    )
    .await;

    Ok(Json(NativeImportResponse {
        path: response_path,
        source: import_source.response_source().to_string(),
        source_label: import_source.response_label().to_string(),
        dry_run: false,
        recursive: body.recursive,
        truncated,
        total_files: files.len(),
        total_bytes,
        store_original_file: body.store_original_file,
        imported: ingest.imported,
        deduped: ingest.deduped,
        failed: ingest.failed,
        chunks_persisted: ingest.chunks_persisted,
        assets_retained: ingest.assets_retained,
        assets_deduped: ingest.assets_deduped,
        asset_links: ingest.asset_links,
        asset_failed: ingest.asset_failed,
        files,
        results: ingest.results,
    }))
}

async fn import_schema_documents(
    data_dir: std::path::PathBuf,
    tenant: Arc<LibraryHandle>,
    principal: Option<String>,
    requested_path: std::path::PathBuf,
    response_path: String,
    source: solo_storage::SchemaImportSource,
    conversations: Vec<String>,
    dry_run: bool,
    max_files: usize,
    store_original_file: bool,
) -> Result<Json<NativeImportResponse>, ApiError> {
    let parse_path = requested_path.clone();
    let scan = tokio::task::spawn_blocking(move || {
        solo_storage::parse_schema_import(&parse_path, source, &conversations).map_err(|e| {
            format!(
                "parse {} import path {}: {e}",
                source.command_name(),
                parse_path.display()
            )
        })
    })
    .await
    .map_err(|e| ApiError::internal(format!("schema import parse task failed: {e}")))?
    .map_err(ApiError::bad_request)?;

    let materialized_dir = data_dir.join("imports").join(source.materialized_dir());
    let mut records = scan.records;
    let truncated = records.len() > max_files;
    records.truncate(max_files);
    let total_bytes = records
        .iter()
        .map(|record| record.body.len() as u64)
        .sum::<u64>();

    let files = tokio::task::spawn_blocking(move || {
        schema_records_to_import_files(&materialized_dir, &records, !dry_run)
    })
    .await
    .map_err(|e| ApiError::internal(format!("schema import materialize task failed: {e}")))?
    .map_err(ApiError::internal)?;

    if dry_run {
        return Ok(Json(NativeImportResponse {
            path: response_path,
            source: source.command_name().to_string(),
            source_label: source.display_name().to_string(),
            dry_run: true,
            recursive: false,
            truncated,
            total_files: files.len(),
            total_bytes,
            store_original_file,
            imported: 0,
            deduped: 0,
            failed: 0,
            chunks_persisted: 0,
            assets_retained: 0,
            assets_deduped: 0,
            asset_links: 0,
            asset_failed: 0,
            files,
            results: Vec::new(),
        }));
    }

    let chunk_config = chunk_config_from_document_config(&tenant.config().documents)?;
    let ingest = ingest_import_files(
        tenant.as_ref(),
        principal,
        &files,
        chunk_config,
        store_original_file,
    )
    .await;

    Ok(Json(NativeImportResponse {
        path: response_path,
        source: source.command_name().to_string(),
        source_label: source.display_name().to_string(),
        dry_run: false,
        recursive: false,
        truncated,
        total_files: files.len(),
        total_bytes,
        store_original_file,
        imported: ingest.imported,
        deduped: ingest.deduped,
        failed: ingest.failed,
        chunks_persisted: ingest.chunks_persisted,
        assets_retained: ingest.assets_retained,
        assets_deduped: ingest.assets_deduped,
        asset_links: ingest.asset_links,
        asset_failed: ingest.asset_failed,
        files,
        results: ingest.results,
    }))
}

fn schema_records_to_import_files(
    materialized_dir: &std::path::Path,
    records: &[solo_storage::ImportRecord],
    write_files: bool,
) -> Result<Vec<NativeImportFile>, String> {
    if write_files {
        std::fs::create_dir_all(materialized_dir)
            .map_err(|e| format!("create {}: {e}", materialized_dir.display()))?;
    }

    records
        .iter()
        .map(|record| {
            let path = if write_files {
                solo_storage::materialize_schema_record(materialized_dir, record)
                    .map_err(|e| e.to_string())?
            } else {
                solo_storage::materialized_schema_record_path(materialized_dir, record)
            };
            Ok(NativeImportFile {
                path: path.display().to_string(),
                bytes: record.body.len() as u64,
                path_buf: path,
            })
        })
        .collect()
}

async fn ingest_import_files(
    tenant: &LibraryHandle,
    principal: Option<String>,
    files: &[NativeImportFile],
    chunk_config: solo_storage::ChunkConfig,
    store_original_file: bool,
) -> NativeImportIngestSummary {
    let mut imported = 0u32;
    let mut deduped = 0u32;
    let mut failed = 0u32;
    let mut chunks_persisted = 0u32;
    let mut assets_retained = 0u32;
    let mut assets_deduped = 0u32;
    let mut asset_links = 0u32;
    let mut asset_failed = 0u32;
    let mut results = Vec::with_capacity(files.len());

    for file in files {
        match tenant
            .write()
            .ingest_document_as(
                principal.clone(),
                file.path_buf.clone(),
                chunk_config.clone(),
            )
            .await
        {
            Ok(report) => {
                let mut asset = None;
                let mut document_asset_link = None;
                let mut asset_error = None;
                if store_original_file {
                    match retain_import_original_file(
                        tenant,
                        principal.clone(),
                        file,
                        report.doc_id,
                    )
                    .await
                    {
                        Ok((stored_asset, link)) => {
                            assets_retained += 1;
                            if stored_asset.deduped {
                                assets_deduped += 1;
                            }
                            asset_links += 1;
                            asset = Some(stored_asset);
                            document_asset_link = Some(link);
                        }
                        Err(err) => {
                            asset_failed += 1;
                            asset_error = Some(err.to_string());
                        }
                    }
                }
                if report.deduped {
                    deduped += 1;
                } else {
                    imported += 1;
                }
                chunks_persisted += report.chunks_persisted;
                results.push(NativeImportResult {
                    path: file.path.clone(),
                    bytes: file.bytes,
                    doc_id: Some(report.doc_id.to_string()),
                    chunks_persisted: report.chunks_persisted,
                    bytes_ingested: report.bytes_ingested,
                    deduped: report.deduped,
                    asset,
                    document_asset_link,
                    asset_error,
                    error: None,
                });
            }
            Err(err) => {
                failed += 1;
                results.push(NativeImportResult {
                    path: file.path.clone(),
                    bytes: file.bytes,
                    doc_id: None,
                    chunks_persisted: 0,
                    bytes_ingested: 0,
                    deduped: false,
                    asset: None,
                    document_asset_link: None,
                    asset_error: None,
                    error: Some(err.to_string()),
                });
            }
        }
    }

    NativeImportIngestSummary {
        imported,
        deduped,
        failed,
        chunks_persisted,
        assets_retained,
        assets_deduped,
        asset_links,
        asset_failed,
        results,
    }
}

async fn retain_import_original_file(
    tenant: &LibraryHandle,
    principal: Option<String>,
    file: &NativeImportFile,
    doc_id: DocumentId,
) -> solo_core::Result<(
    solo_storage::StoredAssetReport,
    solo_storage::DocumentAssetLinkReport,
)> {
    crate::document_upload::retain_original_file_for_document(
        tenant,
        principal,
        doc_id,
        crate::document_upload::RetainOriginalFileRequest {
            path: file.path_buf.clone(),
            filename: file
                .path_buf
                .file_name()
                .and_then(|name| name.to_str())
                .map(str::to_string),
            mime_type: crate::document_upload::document_mime_type_for_path(&file.path_buf),
            size_bytes: Some(file.bytes),
            sha256: None,
            source: Some(file.path.clone()),
            relation_type: "source_import".to_string(),
            note: Some("original local import file".to_string()),
        },
    )
    .await
}

fn chunk_config_from_document_config(
    config: &solo_storage::DocumentConfig,
) -> Result<solo_storage::ChunkConfig, ApiError> {
    if config.chunk_token_target == 0 {
        return Err(ApiError::bad_request(
            "documents.chunk_token_target must be > 0",
        ));
    }
    if config.chunk_overlap_tokens >= config.chunk_token_target {
        return Err(ApiError::bad_request(format!(
            "documents.chunk_overlap_tokens ({}) must be strictly less than documents.chunk_token_target ({})",
            config.chunk_overlap_tokens, config.chunk_token_target
        )));
    }
    Ok(solo_storage::ChunkConfig {
        target_tokens: config.chunk_token_target,
        overlap_tokens: config.chunk_overlap_tokens,
    })
}

fn collect_native_import_files(
    path: &std::path::Path,
    recursive: bool,
    allowed_extensions: &[String],
    max_files: usize,
) -> Result<(Vec<NativeImportFile>, bool), ApiError> {
    let metadata = std::fs::metadata(path).map_err(|e| {
        ApiError::bad_request(format!("path {} is not readable: {e}", path.display()))
    })?;
    if metadata.is_file() {
        if !has_allowed_extension(path, allowed_extensions) {
            return Ok((Vec::new(), false));
        }
        let path_buf = path.to_path_buf();
        return Ok((
            vec![NativeImportFile {
                path: path.display().to_string(),
                bytes: metadata.len(),
                path_buf,
            }],
            false,
        ));
    }
    if !metadata.is_dir() {
        return Err(ApiError::bad_request(format!(
            "path is not a file or directory: {}",
            path.display()
        )));
    }

    let mut files = Vec::new();
    let mut visited_entries = 0usize;
    let truncated = collect_native_import_dir(
        path,
        recursive,
        allowed_extensions,
        max_files,
        &mut visited_entries,
        &mut files,
    )?;
    files.sort_by(|a, b| a.path.cmp(&b.path));
    Ok((files, truncated))
}

fn collect_native_import_dir(
    dir: &std::path::Path,
    recursive: bool,
    allowed_extensions: &[String],
    max_files: usize,
    visited_entries: &mut usize,
    out: &mut Vec<NativeImportFile>,
) -> Result<bool, ApiError> {
    let read = std::fs::read_dir(dir)
        .map_err(|e| ApiError::bad_request(format!("read_dir {}: {e}", dir.display())))?;

    let mut entries = Vec::new();
    let mut entry_cap_reached = false;
    for entry in read {
        if *visited_entries >= MAX_NATIVE_IMPORT_VISITED_ENTRIES {
            entry_cap_reached = true;
            break;
        }
        *visited_entries += 1;
        let entry =
            entry.map_err(|e| ApiError::bad_request(format!("read_dir {}: {e}", dir.display())))?;
        entries.push((entry.path(), entry));
    }
    entries.sort_by(|(a, _), (b, _)| a.cmp(b));

    let mut truncated = entry_cap_reached;
    for (path, entry) in entries {
        if out.len() >= max_files {
            return Ok(true);
        }
        if is_hidden_entry(&path)? {
            continue;
        }
        let file_type = entry
            .file_type()
            .map_err(|e| ApiError::bad_request(format!("file_type {}: {e}", path.display())))?;
        if file_type.is_dir() {
            if recursive {
                if collect_native_import_dir(
                    &path,
                    recursive,
                    allowed_extensions,
                    max_files,
                    visited_entries,
                    out,
                )? {
                    if out.len() >= max_files {
                        return Ok(true);
                    }
                    truncated = true;
                }
            }
        } else if file_type.is_file() && has_allowed_extension(&path, allowed_extensions) {
            let bytes = entry
                .metadata()
                .map_err(|e| ApiError::bad_request(format!("metadata {}: {e}", path.display())))?
                .len();
            out.push(NativeImportFile {
                path: path.display().to_string(),
                bytes,
                path_buf: path,
            });
            if out.len() >= max_files {
                return Ok(true);
            }
        }
    }
    Ok(truncated)
}

fn is_hidden_entry(path: &std::path::Path) -> Result<bool, ApiError> {
    if is_dot_hidden_path(path) {
        return Ok(true);
    }
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|e| ApiError::bad_request(format!("metadata {}: {e}", path.display())))?;
    Ok(has_platform_hidden_attribute(&metadata))
}

fn is_dot_hidden_path(path: &std::path::Path) -> bool {
    path.file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| name.starts_with('.'))
}

#[cfg(windows)]
fn has_platform_hidden_attribute(metadata: &std::fs::Metadata) -> bool {
    use std::os::windows::fs::MetadataExt;
    const FILE_ATTRIBUTE_HIDDEN: u32 = 0x2;
    metadata.file_attributes() & FILE_ATTRIBUTE_HIDDEN != 0
}

#[cfg(target_os = "macos")]
fn has_platform_hidden_attribute(metadata: &std::fs::Metadata) -> bool {
    use std::os::macos::fs::MetadataExt;
    const UF_HIDDEN: u32 = 0x0000_8000;
    metadata.st_flags() & UF_HIDDEN != 0
}

#[cfg(not(any(windows, target_os = "macos")))]
fn has_platform_hidden_attribute(_metadata: &std::fs::Metadata) -> bool {
    false
}

fn has_allowed_extension(path: &std::path::Path, allowed_extensions: &[String]) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .is_some_and(|ext| {
            let ext = ext.trim_start_matches('.');
            allowed_extensions
                .iter()
                .any(|allowed| allowed.trim_start_matches('.').eq_ignore_ascii_case(ext))
        })
}

