async fn status_handler(
    State(state): State<SoloHttpState>,
    TenantExtractor(tenant): TenantExtractor,
) -> Result<Json<StatusResponse>, ApiError> {
    let embedder = tenant.embedder().clone();
    let embedder_runtime = status_embedder_runtime(embedder.as_ref()).await;
    let steward_slot = tenant.steward_slot().read().await;
    let runtime_wired = steward_slot.is_some();
    let runtime_has_llm = steward_slot
        .as_ref()
        .map(|steward| steward.has_llm())
        .unwrap_or(false);
    let runtime_llm = steward_slot
        .as_ref()
        .map(|steward| steward.llm_name().to_string());
    drop(steward_slot);
    let coverage = solo_storage::read_derived_coverage(tenant.read())
        .await
        .map_err(ApiError::from)?;
    let steward_runtime = state.steward_runtime.snapshot().await;
    let steward = status_steward_from_config(
        tenant.config(),
        runtime_wired,
        runtime_has_llm,
        runtime_llm,
        steward_runtime,
        coverage,
    );
    let capabilities = status_capabilities(&embedder_runtime, &steward);
    Ok(Json(StatusResponse {
        ok: true,
        version: solo_core::build_info::version_with_build_metadata(),
        build: solo_core::build_info::get(),
        library: StatusLibrary {
            name: "Community Memory Library",
            ready: true,
        },
        embedder: StatusEmbedder {
            name: embedder.name().to_string(),
            version: embedder.version().to_string(),
            dim: embedder.dim(),
            dtype: format!("{:?}", embedder.dtype()).to_ascii_lowercase(),
            runtime: Some(embedder_runtime),
        },
        mcp: StatusMcp {
            sessions: state.mcp_sessions.len(),
        },
        steward,
        capabilities,
        runtime: StatusRuntime {
            pid: std::process::id(),
            platform: std::env::consts::OS,
            data_dir: state.registry.data_dir().display().to_string(),
        },
    }))
}

async fn status_embedder_runtime(embedder: &dyn Embedder) -> StatusEmbedderRuntime {
    let checked_at_ms = chrono::Utc::now().timestamp_millis();
    if !embedder.name().starts_with("ollama:") {
        return StatusEmbedderRuntime {
            running: true,
            status: "ready".to_string(),
            detail: "in-process embedder is loaded".to_string(),
            checked_at_ms,
        };
    }

    let url = embedder.runtime_probe_url().unwrap_or_else(|| {
        format!(
            "{}/api/tags",
            status_ollama_base_url().trim_end_matches('/')
        )
    });
    let probe = tokio::time::timeout(
        Duration::from_secs(EMBEDDER_STATUS_PROBE_TIMEOUT_SECS),
        reqwest::Client::new().get(&url).send(),
    )
    .await;

    match probe {
        Ok(Ok(response)) if response.status().is_success() => StatusEmbedderRuntime {
            running: true,
            status: "ready".to_string(),
            detail: "Ollama API reachable without loading the embedding model".to_string(),
            checked_at_ms,
        },
        Ok(Ok(response)) => StatusEmbedderRuntime {
            running: false,
            status: "error".to_string(),
            detail: format!("Ollama API probe returned HTTP {}", response.status()),
            checked_at_ms,
        },
        Ok(Err(error)) => StatusEmbedderRuntime {
            running: false,
            status: "error".to_string(),
            detail: format!(
                "Ollama API probe failed: {}",
                compact_status_detail(&error.to_string())
            ),
            checked_at_ms,
        },
        Err(_) => StatusEmbedderRuntime {
            running: false,
            status: "timeout".to_string(),
            detail: format!(
                "Ollama API probe timed out after {EMBEDDER_STATUS_PROBE_TIMEOUT_SECS}s"
            ),
            checked_at_ms,
        },
    }
}

fn status_ollama_base_url() -> String {
    std::env::var(ENV_OLLAMA_BASE_URL)
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| DEFAULT_OLLAMA_BASE_URL.to_string())
}

fn compact_status_detail(detail: &str) -> String {
    const LIMIT: usize = 240;
    let trimmed = detail.trim();
    if trimmed.chars().count() <= LIMIT {
        return trimmed.to_string();
    }
    let mut compact: String = trimmed.chars().take(LIMIT).collect();
    compact.push_str("...");
    compact
}

async fn switch_ollama_embedder_handler(
    State(state): State<SoloHttpState>,
    Json(req): Json<SwitchOllamaEmbedderRequest>,
) -> Result<Json<SwitchOllamaEmbedderResponse>, ApiError> {
    let model = normalize_ollama_model(req.model)?;
    let dim = normalize_ollama_dim(req.dim)?;
    let base_url = normalize_ollama_base_url(req.base_url)?;
    let config_path = state.registry.data_dir().join("solo.config.toml");
    let mut config = SoloConfig::read(&config_path).map_err(ApiError::from)?;
    let previous = config.embedder.clone();
    let next = EmbedderConfig {
        name: format!("ollama:{model}"),
        version: "v1".to_string(),
        dim,
        dtype: "f32".to_string(),
    };
    let changed = previous != next;
    let snapshot_paths = if changed {
        existing_hnsw_snapshot_paths(state.registry.data_dir())
    } else {
        Vec::new()
    };
    if !snapshot_paths.is_empty() {
        return Err(ApiError::conflict(unsafe_embedder_switch_message(
            &previous,
            &next,
            &snapshot_paths,
        )));
    }
    if changed {
        config.embedder = next.clone();
        replace_solo_config(&config_path, &config)?;
    }

    let reembed_command = "solo reembed --gc".to_string();
    let mut environment_commands = vec![format!("setx SOLO_OLLAMA_EMBED_MODEL {model}")];
    if base_url != "http://localhost:11434" {
        environment_commands.push(format!("setx SOLO_OLLAMA_BASE_URL {base_url}"));
    }
    Ok(Json(SwitchOllamaEmbedderResponse {
        changed,
        config_path: config_path.display().to_string(),
        previous: status_embedder_from_config(previous),
        next: status_embedder_from_config(next),
        restart_required: true,
        reembed_required: true,
        reembed_command: reembed_command.clone(),
        environment_commands: environment_commands.clone(),
        next_steps: vec![
            "Stop Solo so the current writer releases the database.".to_string(),
            format!(
                "Optional process defaults for manual launches: {}",
                environment_commands.join(" && ")
            ),
            "For existing profiles, delete HNSW snapshot files before reembed so startup can rebuild from SQL.".to_string(),
            reembed_command,
            "Start Solo again from the tray.".to_string(),
        ],
        note: "Config updated in solo.config.toml. The running daemon cannot change vector backend in-place; reembed before normal use so search and clustering use Ollama vectors.".to_string(),
    }))
}

async fn switch_llm_handler(
    State(state): State<SoloHttpState>,
    Json(req): Json<SwitchLlmRequest>,
) -> Result<Json<SwitchLlmResponse>, ApiError> {
    let mode = req.mode.trim().to_ascii_lowercase();
    let consent = req.hosted_processing_consent.unwrap_or(false);
    let next = match mode.as_str() {
        "none" => LlmSettings::None,
        "anthropic" => {
            require_hosted_processing_consent(consent, "Anthropic")?;
            LlmSettings::Anthropic {
                api_key_env: normalize_env_var_name(req.api_key_env, "ANTHROPIC_API_KEY")?,
                model: normalize_llm_model(req.model, "claude-sonnet-4-6")?,
                hosted_processing_consent: consent,
            }
        }
        "openai" => {
            require_hosted_processing_consent(consent, "OpenAI")?;
            LlmSettings::Openai {
                api_key_env: normalize_env_var_name(req.api_key_env, "OPENAI_API_KEY")?,
                model: normalize_llm_model(req.model, "gpt-5o")?,
                hosted_processing_consent: consent,
            }
        }
        "ollama" => {
            let endpoint = normalize_ollama_endpoint(req.endpoint.as_deref())?;
            let default_base_url = if matches!(endpoint, solo_storage::OllamaEndpointKind::Cloud) {
                "https://ollama.com"
            } else {
                DEFAULT_OLLAMA_BASE_URL
            };
            let base_url = normalize_llm_base_url(req.base_url, default_base_url)?;
            let model = normalize_llm_model(req.model, "qwen3:8b")?;
            let hosted = ollama_processes_off_device(endpoint, &base_url, &model);
            if hosted {
                require_hosted_processing_consent(consent, "Ollama")?;
            }
            let api_key_env = if matches!(endpoint, solo_storage::OllamaEndpointKind::Cloud)
                && !is_loopback_url(&base_url)
            {
                Some(normalize_env_var_name(req.api_key_env, "OLLAMA_API_KEY")?)
            } else {
                req.api_key_env
                    .map(|name| normalize_env_var_name(Some(name), "OLLAMA_API_KEY"))
                    .transpose()?
            };
            LlmSettings::Ollama {
                endpoint,
                base_url,
                model,
                api_key_env,
                hosted_processing_consent: consent,
            }
        }
        "mcp_sampling" => {
            return Err(ApiError::bad_request(
                "`mcp_sampling` requires an MCP stdio peer and is not configurable from the daemon settings API",
            ));
        }
        _ => {
            return Err(ApiError::bad_request(
                "mode must be one of `none`, `anthropic`, `openai`, or `ollama`",
            ));
        }
    };

    let config_path = state.registry.data_dir().join("solo.config.toml");
    let mut config = SoloConfig::read(&config_path).map_err(ApiError::from)?;
    let previous = config.llm.clone();
    let changed = previous.as_ref() != Some(&next);
    if changed {
        config.llm = Some(next.clone());
        replace_solo_config(&config_path, &config)?;
    }

    Ok(Json(SwitchLlmResponse {
        changed,
        config_path: config_path.display().to_string(),
        previous: llm_settings_summary(previous.as_ref()),
        next: llm_settings_summary(Some(&next)),
        restart_required: true,
        environment_commands: llm_environment_commands(&next),
        next_steps: llm_next_steps(&next),
        note: "Steward LLM config is saved in solo.config.toml. Restart Solo from Solo Controls for the running daemon to load it; API keys stay in environment variables and are not stored in the config file.".to_string(),
    }))
}

async fn switch_steward_cadence_handler(
    State(state): State<SoloHttpState>,
    Json(req): Json<StewardCadenceSettingsRequest>,
) -> Result<Json<StewardCadenceSettingsResponse>, ApiError> {
    validate_cadence_u64(
        "trigger_interval_secs",
        req.trigger_interval_secs,
        STEWARD_CADENCE_MAX_INTERVAL_SECS,
    )?;
    validate_cadence_u32(
        "trigger_episode_count",
        req.trigger_episode_count,
        STEWARD_CADENCE_MAX_EPISODE_COUNT,
    )?;
    validate_cadence_u64(
        "consolidate_interval_secs",
        req.consolidate_interval_secs,
        STEWARD_CADENCE_MAX_INTERVAL_SECS,
    )?;
    validate_cadence_u64(
        "cluster_timeout_secs",
        req.cluster_timeout_secs,
        STEWARD_CADENCE_MAX_CLUSTER_TIMEOUT_SECS,
    )?;
    validate_cluster_min_size(req.cluster_min_size)?;
    validate_cluster_cosine_threshold(req.cluster_cosine_threshold)?;

    let config_path = state.registry.data_dir().join("solo.config.toml");
    let mut config = SoloConfig::read(&config_path).map_err(ApiError::from)?;
    let previous_triples = config.triples.clone();
    let previous_steward = config.steward.clone();
    let mut next_triples = previous_triples.clone();
    let mut next_steward = previous_steward.clone();
    if let Some(value) = req.trigger_interval_secs {
        next_triples.trigger_interval_secs = value;
    }
    if let Some(value) = req.trigger_episode_count {
        next_triples.trigger_episode_count = value;
    }
    if let Some(value) = req.consolidate_interval_secs {
        next_triples.consolidate_interval_secs = value;
    }
    if let Some(value) = req.cluster_timeout_secs {
        next_triples.cluster_timeout_secs = value;
    }
    if let Some(value) = req.cluster_min_size {
        next_steward.cluster_min_size = Some(value);
    }
    if let Some(value) = req.cluster_cosine_threshold {
        next_steward.cluster_cosine_threshold = Some(value);
    }

    let changed = previous_triples != next_triples || previous_steward != next_steward;
    if changed {
        config.triples = next_triples.clone();
        config.steward = next_steward.clone();
        replace_solo_config(&config_path, &config)?;
    }

    Ok(Json(StewardCadenceSettingsResponse {
        changed,
        config_path: config_path.display().to_string(),
        previous: steward_cadence_settings_summary(&previous_triples, &previous_steward),
        next: steward_cadence_settings_summary(&next_triples, &next_steward),
        restart_required: true,
        note: "Steward config is saved in solo.config.toml. Restart Solo for the running timers and clustering pipeline to use the new values."
            .to_string(),
    }))
}

async fn runtime_restart_handler(
    State(state): State<SoloHttpState>,
) -> Result<Json<RuntimeRestartResponse>, ApiError> {
    state
        .runtime_control
        .request_restart()
        .map_err(ApiError::conflict)?;
    Ok(Json(RuntimeRestartResponse {
        accepted: true,
        restart_expected: true,
        note: "Solo accepted the restart request. The daemon will shut down cleanly; Solo Controls should start it again."
            .to_string(),
    }))
}

fn existing_hnsw_snapshot_paths(data_dir: &std::path::Path) -> Vec<std::path::PathBuf> {
    let mut dirs = vec![data_dir.to_path_buf(), data_dir.join("tenants")];
    if let Ok(entries) = std::fs::read_dir(data_dir.join("tenants")) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                dirs.push(path);
            }
        }
    }

    let mut paths = Vec::new();
    for dir in dirs {
        for basename in ["hnsw_episodes", "hnsw_episodes_bak", "hnsw_episodes_tmp"] {
            for suffix in [".hnsw.data", ".hnsw.graph"] {
                let path = dir.join(format!("{basename}{suffix}"));
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
    }
    paths.sort();
    paths.dedup();
    paths
}

fn unsafe_embedder_switch_message(
    previous: &EmbedderConfig,
    next: &EmbedderConfig,
    snapshot_paths: &[std::path::PathBuf],
) -> String {
    let first = snapshot_paths
        .first()
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "unknown".to_string());
    format!(
        "Ollama config was not applied because existing HNSW snapshot files are tied to the current embedder ({previous_name}@{previous_version} {previous_dim}d). Switching to {next_name}@{next_version} {next_dim}d requires an offline migration: stop Solo, pull the Ollama embedding model, back up solo.config.toml, edit the [embedder] block, delete HNSW snapshot files, run `solo reembed --gc`, then start Solo. Found {count} snapshot file(s); first: {first}",
        previous_name = previous.name.as_str(),
        previous_version = previous.version.as_str(),
        previous_dim = previous.dim,
        next_name = next.name.as_str(),
        next_version = next.version.as_str(),
        next_dim = next.dim,
        count = snapshot_paths.len(),
    )
}

