fn steward_cadence_settings_summary(
    config: &TriplesConfig,
    steward: &solo_storage::StewardSettings,
) -> StewardCadenceSettingsSummary {
    let cluster_config = solo_steward::StewardConfig::from_settings_then_env(
        steward.cluster_min_size,
        steward.cluster_cosine_threshold,
    )
    .unwrap_or_default();
    StewardCadenceSettingsSummary {
        trigger_interval_secs: config.trigger_interval_secs,
        trigger_episode_count: config.trigger_episode_count,
        consolidate_interval_secs: config.consolidate_interval_secs,
        cluster_timeout_secs: config.cluster_timeout_secs,
        cluster_min_size: cluster_config.cluster_min_size,
        cluster_cosine_threshold: cluster_config.cluster_cosine_threshold,
    }
}

fn validate_cadence_u64(name: &str, value: Option<u64>, max: u64) -> Result<(), ApiError> {
    if let Some(value) = value {
        if value > max {
            return Err(ApiError::bad_request(format!(
                "{name} must be <= {max} seconds"
            )));
        }
    }
    Ok(())
}

fn validate_cadence_u32(name: &str, value: Option<u32>, max: u32) -> Result<(), ApiError> {
    if let Some(value) = value {
        if value > max {
            return Err(ApiError::bad_request(format!("{name} must be <= {max}")));
        }
    }
    Ok(())
}

fn validate_cluster_min_size(value: Option<usize>) -> Result<(), ApiError> {
    if matches!(value, Some(0)) {
        return Err(ApiError::bad_request("cluster_min_size must be >= 1"));
    }
    Ok(())
}

fn validate_cluster_cosine_threshold(value: Option<f32>) -> Result<(), ApiError> {
    if let Some(value) = value {
        if !value.is_finite() || value <= 0.0 || value > 1.0 {
            return Err(ApiError::bad_request(
                "cluster_cosine_threshold must be a finite number in (0.0, 1.0]",
            ));
        }
    }
    Ok(())
}

fn llm_environment_commands(llm: &LlmSettings) -> Vec<String> {
    match llm {
        LlmSettings::Anthropic { api_key_env, .. } => {
            vec![format!("setx {api_key_env} <your-anthropic-api-key>")]
        }
        LlmSettings::Openai { api_key_env, .. } => {
            vec![format!("setx {api_key_env} <your-openai-api-key>")]
        }
        LlmSettings::Ollama {
            endpoint,
            base_url,
            model,
            api_key_env,
            ..
        } => {
            let mut commands = Vec::new();
            if matches!(endpoint, solo_storage::OllamaEndpointKind::Local) {
                commands.push(format!("ollama pull {model}"));
            } else if let Some(api_key_env) = api_key_env {
                commands.push(format!("setx {api_key_env} <your-ollama-api-key>"));
            }
            commands.push(format!("# Ollama endpoint: {base_url}"));
            commands
        }
        LlmSettings::None => Vec::new(),
        LlmSettings::McpSampling => Vec::new(),
    }
}

fn llm_next_steps(llm: &LlmSettings) -> Vec<String> {
    let mut steps = match llm {
        LlmSettings::Anthropic { api_key_env, .. } => vec![format!(
            "Make sure {api_key_env} is set in the environment that launches Solo."
        )],
        LlmSettings::Openai { api_key_env, .. } => vec![format!(
            "Make sure {api_key_env} is set in the environment that launches Solo."
        )],
        LlmSettings::Ollama { endpoint, base_url, model, api_key_env, .. } => match endpoint {
            solo_storage::OllamaEndpointKind::Local => vec![
                format!("Make sure Ollama is running at {base_url}."),
                format!("Pull the local Steward model if needed: ollama pull {model}."),
            ],
            solo_storage::OllamaEndpointKind::Cloud => vec![
                format!("Memory content will be processed by Ollama Cloud through {base_url}."),
                api_key_env.as_ref().map(|name| format!("Make sure {name} is set in the environment that launches Solo.")).unwrap_or_else(|| "Make sure the local Ollama daemon is signed in for cloud-model access.".to_string()),
            ],
            solo_storage::OllamaEndpointKind::Custom => vec![
                format!("Confirm the custom Ollama endpoint is reachable at {base_url}."),
                "Verify the endpoint operator's storage, logging, and retention policy before backfilling memories.".to_string(),
            ],
        },
        LlmSettings::None => vec![
            "Solo will cluster memories only; triples and abstractions stay disabled.".to_string(),
        ],
        LlmSettings::McpSampling => Vec::new(),
    };
    steps.push(
        "Restart Solo from Solo Controls so the daemon loads the new LLM config.".to_string(),
    );
    steps.push(
        "Run consolidation or wait for the configured triples/consolidation cadence.".to_string(),
    );
    steps
}

fn normalize_ollama_model(model: Option<String>) -> Result<String, ApiError> {
    let model = model
        .unwrap_or_else(|| "nomic-embed-text".to_string())
        .trim()
        .to_string();
    if model.is_empty() {
        return Err(ApiError::bad_request("model must not be empty"));
    }
    if model.len() > 128 {
        return Err(ApiError::bad_request(
            "model must be at most 128 characters",
        ));
    }
    if !model
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || matches!(c, ':' | '-' | '_' | '.' | '/'))
    {
        return Err(ApiError::bad_request(
            "model may contain only ASCII letters, numbers, colon, dash, underscore, dot, or slash",
        ));
    }
    Ok(model)
}

fn normalize_ollama_dim(dim: Option<u32>) -> Result<u32, ApiError> {
    let dim = dim.unwrap_or(768);
    if dim == 0 {
        return Err(ApiError::bad_request("dim must be greater than zero"));
    }
    Ok(dim)
}

fn normalize_ollama_base_url(base_url: Option<String>) -> Result<String, ApiError> {
    let base_url = base_url
        .unwrap_or_else(|| "http://localhost:11434".to_string())
        .trim()
        .trim_end_matches('/')
        .to_string();
    if base_url.is_empty() {
        return Err(ApiError::bad_request("base_url must not be empty"));
    }
    if base_url.len() > 512 {
        return Err(ApiError::bad_request(
            "base_url must be at most 512 characters",
        ));
    }
    if !(base_url.starts_with("http://") || base_url.starts_with("https://")) {
        return Err(ApiError::bad_request(
            "base_url must start with http:// or https://",
        ));
    }
    if base_url.chars().any(char::is_whitespace) {
        return Err(ApiError::bad_request(
            "base_url must not contain whitespace",
        ));
    }
    Ok(base_url)
}

fn normalize_llm_base_url(base_url: Option<String>, default: &str) -> Result<String, ApiError> {
    normalize_ollama_base_url(Some(base_url.unwrap_or_else(|| default.to_string())))
}

fn normalize_llm_model(model: Option<String>, default: &str) -> Result<String, ApiError> {
    let model = model
        .unwrap_or_else(|| default.to_string())
        .trim()
        .to_string();
    if model.is_empty() {
        return Err(ApiError::bad_request("model must not be empty"));
    }
    if model.len() > 128 {
        return Err(ApiError::bad_request(
            "model must be at most 128 characters",
        ));
    }
    if model.chars().any(char::is_whitespace) {
        return Err(ApiError::bad_request("model must not contain whitespace"));
    }
    Ok(model)
}

fn normalize_env_var_name(name: Option<String>, default: &str) -> Result<String, ApiError> {
    let name = name
        .unwrap_or_else(|| default.to_string())
        .trim()
        .to_string();
    if name.is_empty() {
        return Err(ApiError::bad_request("api_key_env must not be empty"));
    }
    if name.len() > 128 {
        return Err(ApiError::bad_request(
            "api_key_env must be at most 128 characters",
        ));
    }
    let mut chars = name.chars();
    let Some(first) = chars.next() else {
        return Err(ApiError::bad_request("api_key_env must not be empty"));
    };
    if !(first == '_' || first.is_ascii_alphabetic()) {
        return Err(ApiError::bad_request(
            "api_key_env must start with a letter or underscore",
        ));
    }
    if !chars.all(|c| c == '_' || c.is_ascii_alphanumeric()) {
        return Err(ApiError::bad_request(
            "api_key_env may contain only ASCII letters, numbers, and underscore",
        ));
    }
    Ok(name)
}

fn replace_solo_config(path: &std::path::Path, config: &SoloConfig) -> Result<(), ApiError> {
    let body = toml::to_string_pretty(config)
        .map_err(|e| ApiError::internal(format!("serialize solo.config.toml: {e}")))?;
    let parent = path
        .parent()
        .ok_or_else(|| ApiError::internal("solo.config.toml has no parent directory"))?;
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("solo.config.toml");
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let tmp_path = parent.join(format!("{file_name}.{stamp}.{}.tmp", std::process::id()));
    let backup_path = parent.join(format!("{file_name}.{stamp}.bak"));

    {
        let mut tmp_file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&tmp_path)
            .map_err(|e| ApiError::internal(format!("open tmp {}: {e}", tmp_path.display())))?;
        std::io::Write::write_all(&mut tmp_file, body.as_bytes())
            .map_err(|e| ApiError::internal(format!("write tmp {}: {e}", tmp_path.display())))?;
        tmp_file
            .sync_all()
            .map_err(|e| ApiError::internal(format!("fsync tmp {}: {e}", tmp_path.display())))?;
    }

    std::fs::copy(path, &backup_path).map_err(|e| {
        let _ = std::fs::remove_file(&tmp_path);
        ApiError::internal(format!(
            "backup existing config {}: {e}",
            backup_path.display()
        ))
    })?;

    if let Err(e) = std::fs::remove_file(path) {
        let _ = std::fs::remove_file(&tmp_path);
        let _ = std::fs::remove_file(&backup_path);
        return Err(ApiError::internal(format!(
            "remove old config {}: {e}",
            path.display()
        )));
    }
    if let Err(e) = std::fs::rename(&tmp_path, path) {
        let _ = std::fs::rename(&backup_path, path);
        let _ = std::fs::remove_file(&tmp_path);
        return Err(ApiError::internal(format!(
            "replace config {}: {e}",
            path.display()
        )));
    }
    let _ = std::fs::remove_file(&backup_path);

    Ok(())
}

async fn logs_handler(
    State(state): State<SoloHttpState>,
    Query(query): Query<LogsQuery>,
) -> Result<Json<LogsResponse>, ApiError> {
    let source = query.source.unwrap_or_else(|| "tray".to_string());
    if source != "tray" {
        return Err(ApiError::bad_request("source must be `tray`"));
    }
    let limit = query
        .limit
        .unwrap_or(LOG_TAIL_DEFAULT_LIMIT)
        .clamp(1, LOG_TAIL_MAX_LIMIT);
    let path = state.registry.data_dir().join("tray.log");
    let path_display = path.display().to_string();
    let read = tokio::task::spawn_blocking(move || read_log_tail(path, limit))
        .await
        .map_err(|e| ApiError::internal(format!("join log tail task: {e}")))?
        .map_err(|e| ApiError::internal(format!("read tray log: {e}")))?;

    Ok(Json(LogsResponse {
        source,
        path: path_display,
        exists: read.exists,
        limit,
        size_bytes: read.size_bytes,
        modified_at_ms: read.modified_at_ms,
        lines: read
            .lines
            .into_iter()
            .map(|line| LogTailLine {
                level: line.level,
                text: line.text,
            })
            .collect(),
    }))
}

struct LogTailRead {
    exists: bool,
    size_bytes: Option<u64>,
    modified_at_ms: Option<i64>,
    lines: Vec<crate::log_tail::TailLine>,
}

fn read_log_tail(path: std::path::PathBuf, limit: usize) -> std::io::Result<LogTailRead> {
    let metadata = match std::fs::metadata(&path) {
        Ok(metadata) => metadata,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
            return Ok(LogTailRead {
                exists: false,
                size_bytes: None,
                modified_at_ms: None,
                lines: Vec::new(),
            });
        }
        Err(err) => return Err(err),
    };
    let modified_at_ms = metadata.modified().ok().and_then(system_time_to_epoch_ms);
    let lines = crate::log_tail::read_tail_lines(&path, limit)?;
    Ok(LogTailRead {
        exists: true,
        size_bytes: Some(metadata.len()),
        modified_at_ms,
        lines,
    })
}

fn system_time_to_epoch_ms(time: std::time::SystemTime) -> Option<i64> {
    let duration = time.duration_since(std::time::UNIX_EPOCH).ok()?;
    i64::try_from(duration.as_millis()).ok()
}

// v0.10.2 — MCP-over-HTTP transport on /mcp
// ---------------------------------------------------------------------------

// v0.11.0 P2: the per-event names that used to live here as
// `MCP_STREAM_EVENT_INIT` moved into `crate::mcp_session` alongside the
// `McpEventKind` enum so the publisher (`SessionState::publish_event`)
// and the subscriber (`build_mcp_session_stream`) share one source of
// truth for the wire format. See `MCP_STREAM_EVENT_INIT_NAME`,
// `MCP_STREAM_EVENT_MESSAGE_NAME`, `MCP_STREAM_EVENT_PROGRESS_NAME`,
// `MCP_STREAM_EVENT_LAGGED_NAME`, and `MCP_STREAM_EVENT_HEARTBEAT_NAME`
// for the canonical strings.

/// Validate the optional `MCP-Protocol-Version` request header.
///
/// Per the MCP Streamable HTTP transport spec a client SHOULD echo the
/// negotiated protocol version on every post-`initialize` request, but
/// when the header is **absent** the spec directs the server to fall
/// back to the version negotiated during `initialize` rather than reject
/// the request. Solo always has that version available — every `/mcp`
/// request after init carries an `Mcp-Session-Id` bound to a
/// `SessionState` — so a missing header is accepted and the session's
/// negotiated version stands.
///
/// A header that IS present must still name a version Solo supports; an
/// unsupported, malformed, or duplicated value (e.g. a buggy bridge that
/// sends `"2025-11-25, 2025-11-25"`) stays a `400` so a genuinely
/// incompatible client fails loudly instead of silently talking the
/// wrong dialect.
///
/// History: builds ≤ v0.11.9 hard-required the header on every
/// continuing request, which 400'd well-behaved bridges like
/// `mcp-remote` that omit it on proxied calls. See dev log 0237.
fn validate_mcp_protocol_version_header(
    header: Option<&axum::http::HeaderValue>,
) -> Result<(), Box<Response>> {
    let Some(header) = header else {
        // Absent header → fall back to the session-negotiated version.
        return Ok(());
    };

    let version = header.to_str().map_err(|e| {
        Box::new(
            (
                StatusCode::BAD_REQUEST,
                Json(serde_json::json!({
                    "error": format!(
                        "{} must be an ASCII protocol version: {e}",
                        crate::mcp_protocol::MCP_PROTOCOL_VERSION_HEADER
                    ),
                    "status": 400,
                })),
            )
                .into_response(),
        )
    })?;
    if crate::mcp_protocol::is_supported_protocol_version(version) {
        Ok(())
    } else {
        Err(Box::new(
            (
                StatusCode::BAD_REQUEST,
                Json(serde_json::json!({
                    "error": format!(
                        "unsupported `{}` value `{version}`",
                        crate::mcp_protocol::MCP_PROTOCOL_VERSION_HEADER
                    ),
                    "status": 400,
                    "supported_versions": crate::mcp_protocol::MCP_SUPPORTED_PROTOCOL_VERSIONS,
                })),
            )
                .into_response(),
        ))
    }
}

/// `POST /mcp` — JSON-RPC request/response.
///
/// v0.10.2 P2 entry point. Per the MCP Streamable HTTP transport spec,
/// the body is one JSON-RPC 2.0 envelope (`{jsonrpc, id, method,
/// params}`). The response is one JSON-RPC envelope (`{jsonrpc, id,
/// result}` or `{jsonrpc, id, error}`) with `Content-Type:
/// application/json`. **Status 200** for valid JSON-RPC (in-body
/// errors); **status 400** for malformed JSON; **status 401** when
/// auth is configured and the bearer check fails (handled by the
/// `auth_middleware` ahead of this handler).
///
/// HTTP and stdio both bind to the one Community Memory Library. The audit
/// principal is `Some("bearer")` for bearer-authenticated calls and the JWT
/// `sub` for OIDC; `None` for unauthenticated loopback.
async fn mcp_http_post_handler(
    TenantExtractor(tenant): TenantExtractor,
    State(state): State<SoloHttpState>,
    AuditPrincipal(principal): AuditPrincipal,
    request: axum::extract::Request,
) -> Response {
    // v0.11.0 P1: read the session extension the middleware planted on
    // a hit; if absent, this is the session-init request — create one
    // and echo the assigned id back via `Mcp-Session-Id`.
    let existing_session_id: Option<crate::mcp_session::SessionId> = request
        .extensions()
        .get::<crate::mcp_session::SessionId>()
        .cloned();
    let protocol_version_header = request
        .headers()
        .get(crate::mcp_protocol::MCP_PROTOCOL_VERSION_HEADER)
        .cloned();
    let principal_full = request
        .extensions()
        .get::<crate::auth::AuthenticatedPrincipal>()
        .cloned();
    let existing_session_state = request
        .extensions()
        .get::<std::sync::Arc<crate::mcp_session::SessionState>>()
        .cloned();
    let body_bytes = match axum::body::to_bytes(
        request.into_body(),
        // Match the 8 MiB cap solo-api already uses for JSON bodies in
        // other handlers (validated by `tower-http::limit::RequestBodyLimitLayer`
        // elsewhere). Locally we cap at 8 MiB so a malformed Content-Length
        // can't OOM the dispatch task.
        8 * 1024 * 1024,
    )
    .await
    {
        Ok(b) => b,
        Err(e) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(serde_json::json!({
                    "error": format!("invalid request body: {e}"),
                    "status": 400,
                })),
            )
                .into_response();
        }
    };
    // Parse the JSON-RPC envelope. Malformed input ⇒ 400 (the spec
    // calls out 4xx for malformed wire input even though JSON-RPC's own
    // parse-error code is in-body — operator-facing tooling needs the
    // HTTP status to distinguish "the server rejected the request
    // shape" from "the method returned an error").
    let request: crate::mcp_dispatch::JsonRpcRequest = match serde_json::from_slice(&body_bytes) {
        Ok(r) => r,
        Err(e) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(serde_json::json!({
                    "error": format!("invalid JSON-RPC request: {e}"),
                    "status": 400,
                })),
            )
                .into_response();
        }
    };
    if request.jsonrpc != "2.0" {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "error": format!(
                    "invalid JSON-RPC request: expected jsonrpc=\"2.0\", got {:?}",
                    request.jsonrpc
                ),
                "status": 400,
            })),
        )
            .into_response();
    }
    if let Err(response) = validate_mcp_protocol_version_header(protocol_version_header.as_ref()) {
        return *response;
    }

    // v0.11.0 P1: assign a session id if the request arrived without
    // one. The assigned id is echoed back via the `Mcp-Session-Id`
    // response header so the client can reuse it.
    let (session_id, freshly_assigned) = match existing_session_id {
        Some(id) => (id, false),
        None => {
            let new_state = crate::mcp_session::SessionState::new(principal_full);
            let id = state.mcp_sessions.insert(new_state);
            (id, true)
        }
    };

    // v0.11.0 P3: resolve the `Arc<SessionState>` for the dispatcher so
    // per-tool progress events can be published into the session's
    // broadcast channel. On a session-init request we just inserted
    // the state; for a continuing request the middleware planted an
    // Arc onto the request extensions, but we lost ownership when we
    // consumed the request above (`request.into_body()`). Re-fetch
    // via `mcp_sessions.get(&session_id)` — this is a single lock-free
    // DashMap shard read.
    let session_state: Option<std::sync::Arc<crate::mcp_session::SessionState>> =
        existing_session_state.or_else(|| state.mcp_sessions.get(&session_id));

    // v0.11.0 P4: on a freshly-assigned session, spawn the
    // invalidate-bridge task that forwards per-tenant `InvalidateEvent`
    // broadcasts to this session's event channel as MCP
    // `notifications/message` envelopes. Skipped for continuing requests
    // because the bridge spawned at session-init is still running (the
    // bridge auto-exits when the session drops from the store via the
    // `Weak<SessionState>` upgrade-fails path).
    if freshly_assigned && let Some(session_state_for_bridge) = session_state.clone() {
        // The JoinHandle is intentionally detached — the bridge task
        // owns its own exit path (Weak<SessionState> upgrade fails or
        // tenant broadcast closes). Holding the handle would require
        // a per-session reaper; the bridge's own lifecycle is enough.
        // `drop` is the clippy-clean way to discard a future.
        drop(crate::mcp_notify::spawn_invalidate_bridge(
            tenant.clone(),
            session_state_for_bridge,
        ));
    }

    // Build the dispatcher with the resolved tenant + audit principal.
    // Dispatcher integration is Option B per v0.11.0 P1 plan: sessions
    // are HTTP-transport-only; the dispatcher stays session-agnostic.
    let dispatcher = crate::mcp_dispatch::McpDispatcher::new_with_workspace_file_access_and_tasks(
        state.registry.clone(),
        tenant,
        (*state.user_aliases).clone(),
        principal,
        state.workspace_file_access.clone(),
        state.mcp_tasks.clone(),
    );

    let mut response = match dispatcher.dispatch(request, session_state).await {
        Some(response) => {
            // JSON-RPC errors are in-body; the HTTP status is 200 for
            // any valid JSON-RPC request, including ones that return an
            // error envelope. The client distinguishes success from
            // error by the presence of `result` vs `error` in the body.
            (StatusCode::OK, Json(response)).into_response()
        }
        None => {
            // Notification: per JSON-RPC 2.0 §4.1 the server MUST NOT
            // respond. The MCP Streamable HTTP transport spec uses
            // 202 Accepted for this shape so client-side polling does
            // not block on a body.
            StatusCode::ACCEPTED.into_response()
        }
    };
    // v0.11.0 P1: stamp the `Mcp-Session-Id` response header on every
    // response — both freshly-assigned (so the client learns it) and
    // continuing (so the client confirms the id is still valid). The
    // spec is loose here; echoing always is the safer client contract.
    crate::mcp_session::set_session_id_header(response.headers_mut(), &session_id);
    // Tracing hook lets operators see new-session creation rate in
    // `solo daemon` logs without grepping body bytes.
    if freshly_assigned {
        tracing::debug!(
            session_id = %session_id,
            "mcp-http: assigned new session id"
        );
    }
    response
}

/// Heartbeat cadence for the resumable `/mcp` GET stream. Matches the
/// `/v1/graph/stream` discipline (30s) so operator tooling can use one
/// timeout knob. v0.11.0 P2 makes this configurable indirectly via the
/// helper signature of [`build_mcp_session_stream`] so tests can pass
/// a short interval without driving the real clock for 30s.
pub const MCP_STREAM_HEARTBEAT_SECS: u64 = 30;

/// `GET /mcp` — resumable Server-Sent Events stream for one MCP session.
///
/// v0.11.0 P2 replaces v0.10.2's `pending().await` stub with a real
/// `select!` loop over the session's broadcast event channel. Per the
/// MCP Streamable HTTP transport spec, the GET endpoint is the
/// server's path to push:
///
///   - `event: init` — handshake confirming the stream is live;
///   - `event: message` — JSON-RPC `notifications/message` (P4 bridge);
///   - `event: progress` — JSON-RPC `notifications/progress` (P3 long
///     tool calls);
///   - `event: heartbeat` — periodic liveness ping every
///     [`MCP_STREAM_HEARTBEAT_SECS`] seconds;
///   - `event: lagged` — emitted once when a reconnecting client's
///     `Last-Event-ID` is older than the broadcast buffer's oldest
///     retained event (Decision E).
///
/// Wire format per the SSE spec — each event carries:
/// `id: <u64>\nevent: <kind>\ndata: <json>\n\n`. The `id:` field is the
/// monotonic per-session event id; clients echo the last-seen value
/// back in the `Last-Event-ID` header on reconnect to drive the
/// replay-from-cursor path.
///
/// **Session id REQUIRED.** Unlike `POST /mcp` (which auto-creates a
/// session on the session-init request), `GET /mcp` returns `404 Not
/// Found` if the request arrived without a `Mcp-Session-Id` header.
/// The GET stream's whole point is to attach to an existing session's
/// notification channel — a client opening a stream without a session
/// to attach it to is a programming error, not the entry point to the
/// session lifecycle.
async fn mcp_http_get_handler(
    TenantExtractor(_tenant): TenantExtractor,
    State(state): State<SoloHttpState>,
    AuditPrincipal(principal): AuditPrincipal,
    request: axum::extract::Request,
) -> Response {
    let _ = principal; // audit principal pre-resolved by extractor; unused on GET
    let _ = state; // session resolution lives in the middleware; state unused here

    // v0.11.0 P2: session is REQUIRED on GET. The middleware planted
    // the SessionId + Arc<SessionState> extensions on a hit. If the
    // request arrived without an `Mcp-Session-Id` header, the
    // middleware passes through (so unauth'd POSTs can session-init);
    // we observe that as a missing extension and return 404 here.
    let session_id = match request.extensions().get::<crate::mcp_session::SessionId>() {
        Some(id) => id.clone(),
        None => {
            return (
                StatusCode::NOT_FOUND,
                Json(serde_json::json!({
                    "error": crate::mcp_session::MCP_SESSION_EXPIRED_ERROR,
                    "status": 404,
                    "message": "GET /mcp requires an `Mcp-Session-Id` header \
                                from a prior POST /mcp; open one first",
                    "retry": "re-initialize",
                })),
            )
                .into_response();
        }
    };
    let session_state = match request
        .extensions()
        .get::<std::sync::Arc<crate::mcp_session::SessionState>>()
    {
        Some(state) => state.clone(),
        None => {
            // Defensive: middleware should plant both extensions
            // together or neither, but log + 404 if we somehow see one
            // without the other.
            tracing::error!(
                "mcp_http_get_handler: SessionId extension present but \
                 SessionState extension missing — middleware bug"
            );
            return StatusCode::INTERNAL_SERVER_ERROR.into_response();
        }
    };

    // Optional `Last-Event-ID` header — parse as u64; on parse failure
    // treat as `0` (the "never seen anything" sentinel) so a
    // malformed header doesn't 400 the reconnect.
    if let Err(response) = validate_mcp_protocol_version_header(
        request
            .headers()
            .get(crate::mcp_protocol::MCP_PROTOCOL_VERSION_HEADER),
    ) {
        return *response;
    }

    let last_event_id: u64 = request
        .headers()
        .get(crate::mcp_session::MCP_LAST_EVENT_ID_HEADER)
        .and_then(|v| v.to_str().ok())
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(0);

    let stream = build_mcp_session_stream(
        session_state,
        session_id.clone(),
        last_event_id,
        MCP_STREAM_HEARTBEAT_SECS,
    );
    // No axum keep-alive comment lines — we ship our own typed
    // `heartbeat` event the way `/v1/graph/stream` does. Setting the
    // axum-side interval to 1 hour effectively disables it; clients
    // distinguish liveness via the typed events on the stream.
    let sse = Sse::new(stream).keep_alive(KeepAlive::new().interval(Duration::from_secs(3600)));
    let mut response = sse.into_response();
    crate::mcp_session::set_session_id_header(response.headers_mut(), &session_id);
    response
}

/// `DELETE /mcp` — explicit session termination (v0.11.4, MCP
/// Streamable HTTP transport spec).
///
/// The Streamable HTTP spec defines DELETE on the endpoint as a
/// client-driven session-close. Without it, sessions persist until the
/// sweep-task evicts them by timeout. With it, well-behaved clients
/// (Claude Desktop, ChatGPT MCP connector, scripted MCP clients) can
/// signal "I'm done" so the server reclaims resources immediately.
///
/// Semantics:
///   - Requires `Mcp-Session-Id` header. If absent → 400 Bad Request.
///     (Unlike `GET /mcp` which returns 404 in the same case — that
///     code reflected a different intent. DELETE without a session id
///     is malformed, not "not found", because there is nothing for the
///     client to retry by reinitialising.)
///   - If the session id is unknown to the store → 404 (the spec is
///     permissive here; some servers accept-and-ignore, but operators
///     benefit from the explicit "session you named doesn't exist").
///   - On success → 204 No Content. Body intentionally empty: the
///     contract is "session is gone".
///
/// The middleware does NOT plant session extensions on DELETE (it only
/// validates session-id presence for POST + GET); we read the header
/// directly here so the contract stays self-evident.
async fn mcp_http_delete_handler(
    State(state): State<SoloHttpState>,
    request: axum::extract::Request,
) -> Response {
    let session_id_str = match request
        .headers()
        .get(crate::mcp_session::MCP_SESSION_ID_HEADER)
        .and_then(|v| v.to_str().ok())
    {
        Some(s) => s.to_string(),
        None => {
            return (
                StatusCode::BAD_REQUEST,
                Json(serde_json::json!({
                    "error": "missing required `Mcp-Session-Id` header",
                    "status": 400,
                })),
            )
                .into_response();
        }
    };
    let Some(session_id) = crate::mcp_session::SessionId::parse(&session_id_str) else {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "error": "malformed `Mcp-Session-Id` header",
                "status": 400,
            })),
        )
            .into_response();
    };
    if let Err(response) = validate_mcp_protocol_version_header(
        request
            .headers()
            .get(crate::mcp_protocol::MCP_PROTOCOL_VERSION_HEADER),
    ) {
        return *response;
    }
    if state.mcp_sessions.delete(&session_id) {
        StatusCode::NO_CONTENT.into_response()
    } else {
        (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "error": format!("session `{session_id}` not found"),
                "status": 404,
            })),
        )
            .into_response()
    }
}

/// Per-subscriber state threaded through `futures::stream::unfold` for
/// the resumable `/mcp` GET stream. Carries the broadcast receiver +
/// heartbeat ticker + the queue of replay events (if any) that need
/// to drain before live events start flowing.
///
/// Holds an `Arc<SessionState>` for the SOLE purpose of keeping the
/// broadcast `Sender` alive for as long as this subscriber's stream
/// is open. Without that strong ref, dropping the only Arc the
/// handler held would close the channel and `rx.recv()` would
/// immediately return `Err(Closed)` — the integration test for the
/// heartbeat cadence caught this regression.
struct McpStreamState {
    /// Live event receiver subscribed BEFORE the replay snapshot is
    /// drained — so any event published during the replay window
    /// lands here and the subscriber's `last_replayed_id` cursor
    /// dedupes it against the replayed copy.
    rx: broadcast::Receiver<crate::mcp_session::McpStreamEvent>,
    /// Heartbeat tick — fires every `heartbeat_secs` regardless of
    /// real-event volume. Matches `/v1/graph/stream`'s discipline.
    heartbeat: tokio::time::Interval,
    /// FIFO queue of replay events still to emit before live events
    /// take over. Empties to `Vec::new()` after the last drain.
    replay_queue: Vec<crate::mcp_session::McpStreamEvent>,
    /// `Some(id)` once at least one event has been emitted (replayed
    /// OR live). Live broadcast events with `id <= last_emitted_id`
    /// are skipped — handles the race where an event lands in BOTH
    /// the replay snapshot AND the live broadcast receiver (because
    /// we subscribed before snapshotting).
    last_emitted_id: Option<u64>,
    /// `true` until the synthetic `event: init` has been emitted.
    /// Flipped to `false` on first poll.
    needs_init: bool,
    /// Init-event payload metadata. Pre-computed at handler entry so
    /// the unfold closure stays `Send`.
    session_id_str: String,
    /// Held only to keep the broadcast `Sender` (and thus the channel)
    /// alive for the stream's lifetime. The session store also holds
    /// an Arc, but that one expires under TTL — this Arc keeps the
    /// channel open for this single subscriber for as long as the
    /// client is connected.
    _session_state: std::sync::Arc<crate::mcp_session::SessionState>,
}

/// Build the resumable SSE stream for one `/mcp` GET subscriber.
///
/// Flow per `unfold` iteration:
///
///   1. **needs_init poll** — emit one `event: init` with id 0 (we
///      never allocate event id 0 in `SessionState::publish_event`;
///      0 is reserved for the init event + the client's "never seen"
///      sentinel on `Last-Event-ID`). Returns immediately.
///   2. **replay drain** — while `replay_queue` is non-empty, pop the
///      front entry and emit it. Updates `last_emitted_id`.
///   3. **live select** — `tokio::select!` between
///      `rx.recv()` and `heartbeat.tick()`:
///      - `rx.recv() = Ok(event)` and `event.id > last_emitted_id` →
///        emit and update cursor;
///      - `rx.recv() = Ok(event)` and `event.id <= last_emitted_id` →
///        skip (dedupe overlap with the replayed copy);
///      - `rx.recv() = Err(Lagged(n))` → emit one synthetic
///        `event: lagged` with `data: {dropped: n}` and continue;
///      - `rx.recv() = Err(Closed)` → end the stream (session
///        dropped);
///      - `heartbeat.tick()` → emit an unaccounted-id `event: heartbeat`
///        (heartbeats DO NOT consume the session's event id space —
///        they're synthetic and idempotent, so a reconnecting client
///        doesn't need to see them in replay).
///
/// Heartbeats use SSE event id `0` (the same id space the init event
/// uses) and clients filter them client-side; the broadcast-channel
/// events use the session's real monotonic ids.
fn build_mcp_session_stream(
    session_state: std::sync::Arc<crate::mcp_session::SessionState>,
    session_id: crate::mcp_session::SessionId,
    last_event_id: u64,
    heartbeat_secs: u64,
) -> impl Stream<Item = Result<Event, Infallible>> {
    // 1. Subscribe BEFORE snapshotting so any event published during
    //    the snapshot window lands in the live receiver. We dedupe
    //    overlap against `last_emitted_id` below.
    let rx = session_state.subscribe_events();

    // 2. Snapshot the replay buffer, then filter to events the client
    //    hasn't seen.
    let snapshot = session_state.snapshot_replay_buffer();

    // 3. Decide replay shape based on `last_event_id` vs the snapshot.
    let mut replay_queue: Vec<crate::mcp_session::McpStreamEvent> = Vec::new();
    if last_event_id > 0 {
        // Client is reconnecting with a known cursor.
        let oldest_in_buffer = snapshot.first().map(|e| e.id);
        let newest_in_buffer = snapshot.last().map(|e| e.id);
        if let (Some(oldest), Some(newest)) = (oldest_in_buffer, newest_in_buffer) {
            if last_event_id + 1 < oldest {
                // Client missed events that have since been evicted
                // from the buffer. Emit one synthetic `event: lagged`
                // describing the gap, then resume from the buffer.
                let dropped = oldest.saturating_sub(last_event_id + 1);
                replay_queue.push(crate::mcp_session::McpStreamEvent {
                    id: 0,
                    event: crate::mcp_session::McpEventKind::Lagged,
                    data: serde_json::json!({
                        "dropped": dropped,
                        "last_event_id": last_event_id,
                        "oldest_available": oldest,
                    }),
                });
                replay_queue.extend(snapshot);
            } else if last_event_id >= newest {
                // Client is already caught up; nothing to replay.
            } else {
                replay_queue.extend(snapshot.into_iter().filter(|e| e.id > last_event_id));
            }
        }
        // Empty snapshot + non-zero last_event_id: nothing to replay.
    }
    // last_event_id == 0: brand-new subscriber; no replay needed
    // (the `init` event below is the start of the stream from the
    // client's POV).

    let start_at = tokio::time::Instant::now() + Duration::from_secs(heartbeat_secs);
    let heartbeat = tokio::time::interval_at(start_at, Duration::from_secs(heartbeat_secs));

    let stream_state = McpStreamState {
        rx,
        heartbeat,
        replay_queue,
        last_emitted_id: None,
        needs_init: true,
        session_id_str: session_id.to_string(),
        _session_state: session_state,
    };

    futures::stream::unfold(stream_state, move |mut state| async move {
        // Phase 1: init event (one-shot).
        if state.needs_init {
            state.needs_init = false;
            let init_payload = serde_json::json!({
                "connected": true,
                "session_id": state.session_id_str,
                "ts_ms": chrono::Utc::now().timestamp_millis(),
            });
            let ev = build_mcp_sse_event(0, crate::mcp_session::McpEventKind::Init, &init_payload);
            return Some((Ok::<Event, Infallible>(ev), state));
        }
        // Phase 2: replay-queue drain (one entry per poll).
        if !state.replay_queue.is_empty() {
            let entry = state.replay_queue.remove(0);
            // Lagged synthetic entries don't bump last_emitted_id —
            // they have id 0 and consuming them as the cursor would
            // cause every subsequent live event to dedupe against
            // them. Real events DO bump the cursor.
            if entry.event != crate::mcp_session::McpEventKind::Lagged {
                state.last_emitted_id = Some(entry.id);
            }
            let ev = build_mcp_sse_event(entry.id, entry.event, &entry.data);
            return Some((Ok::<Event, Infallible>(ev), state));
        }
        // Phase 3: live select loop.
        loop {
            tokio::select! {
                event = state.rx.recv() => {
                    match event {
                        Ok(ev) => {
                            // Dedupe against the replay overlap: any
                            // event whose id we've already emitted
                            // (because it was in the replay snapshot)
                            // gets skipped here.
                            if let Some(last) = state.last_emitted_id
                                && ev.id <= last
                            {
                                continue;
                            }
                            state.last_emitted_id = Some(ev.id);
                            let sse = build_mcp_sse_event(ev.id, ev.event, &ev.data);
                            return Some((Ok::<Event, Infallible>(sse), state));
                        }
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            // Live subscriber drifted past the
                            // broadcast buffer's capacity. Emit one
                            // synthetic `event: lagged` and resume —
                            // clients re-fetch state on this signal.
                            tracing::warn!(
                                lagged = n,
                                session_id = %state.session_id_str,
                                "mcp GET stream subscriber lagged"
                            );
                            let lagged_payload = serde_json::json!({
                                "dropped": n,
                            });
                            let sse = build_mcp_sse_event(
                                0,
                                crate::mcp_session::McpEventKind::Lagged,
                                &lagged_payload,
                            );
                            return Some((Ok::<Event, Infallible>(sse), state));
                        }
                        Err(broadcast::error::RecvError::Closed) => {
                            tracing::debug!(
                                session_id = %state.session_id_str,
                                "mcp GET stream broadcast closed; ending SSE stream"
                            );
                            return None;
                        }
                    }
                }
                _ = state.heartbeat.tick() => {
                    let hb_payload = serde_json::json!({
                        "ts_ms": chrono::Utc::now().timestamp_millis(),
                    });
                    let sse = build_mcp_sse_event(
                        0,
                        crate::mcp_session::McpEventKind::Heartbeat,
                        &hb_payload,
                    );
                    return Some((Ok::<Event, Infallible>(sse), state));
                }
            }
        }
    })
}

/// Build an SSE [`Event`] from a `(id, kind, payload)` triple. Falls
/// back to an event-only frame on JSON serialisation failure (matches
/// `/v1/graph/stream`'s defensive pattern).
fn build_mcp_sse_event(
    id: u64,
    kind: crate::mcp_session::McpEventKind,
    data: &serde_json::Value,
) -> Event {
    Event::default()
        .id(id.to_string())
        .event(kind.as_str())
        .json_data(data)
        .unwrap_or_else(|_| Event::default().id(id.to_string()).event(kind.as_str()))
}

// ---------------------------------------------------------------------------
// Error mapping
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub struct ApiError {
    status: StatusCode,
    message: String,
}

impl ApiError {
    fn bad_request(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::BAD_REQUEST,
            message: msg.into(),
        }
    }
    fn not_found(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::NOT_FOUND,
            message: msg.into(),
        }
    }
    fn forbidden(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::FORBIDDEN,
            message: msg.into(),
        }
    }
    fn conflict(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::CONFLICT,
            message: msg.into(),
        }
    }
    fn internal(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            message: msg.into(),
        }
    }
}

impl From<solo_core::Error> for ApiError {
    fn from(e: solo_core::Error) -> Self {
        use solo_core::Error;
        match e {
            Error::NotFound(msg) => ApiError::not_found(msg),
            Error::InvalidInput(msg) => ApiError::bad_request(msg),
            Error::Conflict(msg) => Self {
                status: StatusCode::CONFLICT,
                message: msg,
            },
            Error::Forbidden(msg) => ApiError::forbidden(msg),
            other => ApiError::internal(other.to_string()),
        }
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let body = serde_json::json!({
            "error": self.message,
            "status": self.status.as_u16(),
        });
        (self.status, Json(body)).into_response()
    }
}

