    fn minimal_png(width: u32, height: u32) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
        out.extend_from_slice(&13u32.to_be_bytes());
        out.extend_from_slice(b"IHDR");
        out.extend_from_slice(&width.to_be_bytes());
        out.extend_from_slice(&height.to_be_bytes());
        out
    }

    fn minimal_blend(pointer_size_marker: u8, endian_marker: u8, version: &[u8; 3]) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(b"BLENDER");
        out.push(pointer_size_marker);
        out.push(endian_marker);
        out.extend_from_slice(version);
        out
    }

    fn minimal_gltf_json() -> Vec<u8> {
        br#"{
  "asset": { "version": "2.0", "generator": "Solo fixture" },
  "scene": 0,
  "scenes": [{ "name": "Main Scene", "nodes": [0] }],
  "nodes": [{ "name": "Root Node", "mesh": 0 }],
  "meshes": [{ "name": "Cube Mesh", "primitives": [{ "attributes": { "POSITION": 0 } }] }],
  "materials": [{ "name": "Blue Material" }],
  "buffers": [{ "byteLength": 12 }]
}"#
        .to_vec()
    }

    fn minimal_glb() -> Vec<u8> {
        let mut json = minimal_gltf_json();
        while !json.len().is_multiple_of(4) {
            json.push(b' ');
        }
        let bin = [0u8; 4];
        let total_len = 12 + 8 + json.len() + 8 + bin.len();
        let mut out = Vec::new();
        out.extend_from_slice(b"glTF");
        out.extend_from_slice(&2u32.to_le_bytes());
        out.extend_from_slice(&(total_len as u32).to_le_bytes());
        out.extend_from_slice(&(json.len() as u32).to_le_bytes());
        out.extend_from_slice(b"JSON");
        out.extend_from_slice(&json);
        out.extend_from_slice(&(bin.len() as u32).to_le_bytes());
        out.extend_from_slice(b"BIN\0");
        out.extend_from_slice(&bin);
        out
    }

    fn minimal_blank_pdf() -> Vec<u8> {
        minimal_pdf_with_content_stream("")
    }

    fn minimal_pdf_with_content_stream(stream: &str) -> Vec<u8> {
        let contents = format!(
            "5 0 obj\n<< /Length {} >>\nstream\n{}endstream\nendobj\n",
            stream.len(),
            stream
        );
        let objects: [&str; 5] = [
            "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n",
            "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n",
            "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n",
            "4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n",
            &contents,
        ];

        let mut buf = Vec::new();
        buf.extend_from_slice(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n");
        let mut offsets: Vec<usize> = Vec::with_capacity(objects.len());
        for obj in &objects {
            offsets.push(buf.len());
            buf.extend_from_slice(obj.as_bytes());
        }
        let xref_offset = buf.len();
        buf.extend_from_slice(format!("xref\n0 {}\n", objects.len() + 1).as_bytes());
        buf.extend_from_slice(b"0000000000 65535 f \n");
        for off in &offsets {
            buf.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
        }
        buf.extend_from_slice(
            format!(
                "trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{}\n%%EOF\n",
                objects.len() + 1,
                xref_offset
            )
            .as_bytes(),
        );
        buf
    }

    fn stored_zip(entries: &[(&str, &str)]) -> Vec<u8> {
        use std::io::{Cursor, Write};

        let options = zip::write::SimpleFileOptions::default()
            .compression_method(zip::CompressionMethod::Stored);
        let cursor = Cursor::new(Vec::new());
        let mut zip = zip::ZipWriter::new(cursor);
        for (name, body) in entries {
            zip.start_file(*name, options).expect("start zip entry");
            zip.write_all(body.as_bytes()).expect("write zip entry");
        }
        zip.finish().expect("finish zip").into_inner()
    }

    #[test]
    fn health_returns_ok() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let (status, _body) = runtime.block_on(call(r, "GET", "/health", None));
        assert_eq!(status, StatusCode::OK);
        h.shutdown(&runtime);
    }

    /// `GET /openapi.json` returns a parseable OpenAPI 3.x document with
    /// the four `memory.*` endpoints + their request/response schemas.
    /// Acts as a drift detector: if a future commit adds/removes a route
    /// without updating `openapi_spec`, this test fails loudly.
    #[test]
    fn openapi_json_describes_all_endpoints() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let (status, spec) = runtime.block_on(call(r, "GET", "/openapi.json", None));
        assert_eq!(status, StatusCode::OK);
        assert!(spec.is_object(), "openapi.json must be a JSON object");

        // Top-level shape per OpenAPI 3.1.
        assert!(
            spec.get("openapi")
                .and_then(|v| v.as_str())
                .is_some_and(|s| s.starts_with("3.")),
            "missing or wrong openapi version: {spec}"
        );
        assert!(spec.pointer("/info/title").is_some());
        assert!(spec.pointer("/info/version").is_some());

        // Every route the router serves must be documented.
        let paths = spec
            .get("paths")
            .and_then(|v| v.as_object())
            .expect("paths must be an object");
        for expected in [
            "/health",
            "/openapi.json",
            "/memory",
            "/memory/search",
            "/memory/context",
            "/memory/consolidate",
            "/memory/triples/extract",
            "/memory/derived/repair",
            "/memory/{id}",
            "/backup",
            // Path 1 derived-layer endpoints (v0.4.0+):
            "/memory/themes",
            "/memory/facts_about",
            "/memory/entities",
            "/memory/entities/split-review",
            "/memory/quality/audit",
            "/memory/quality/reviews",
            "/memory/quality/reviews/{review_id}",
            "/memory/contradictions",
            "/memory/contradictions/resolve",
            "/v1/project/facts",
            "/v1/project/decisions",
            "/v1/project/decisions/search",
            "/v1/project/policy",
            // v0.5.0 Priority 3:
            "/memory/clusters/{cluster_id}",
            // v0.7.0 P6 — document operations:
            "/memory/documents",
            "/memory/documents/import",
            "/memory/documents/uploads",
            "/memory/documents/uploads/{upload_id}",
            "/memory/documents/uploads/{upload_id}/commit",
            "/memory/documents/staged/ingest",
            "/memory/documents/search",
            "/memory/documents/{id}",
            "/uploads/{upload_id}",
            // solo-web graph and Community status endpoints:
            "/v1/graph/expand",
            "/v1/graph/nodes",
            "/v1/graph/edges",
            "/v1/graph/paths",
            "/v1/graph/relationships/{edge_id}",
            "/v1/graph/inspect/{id}",
            "/v1/graph/neighbors/{id}",
            "/v1/graph/stream",
            "/v1/inbox",
            "/v1/inbox/{id}/review",
            "/v1/status",
            "/v1/steward/backfill",
            "/v1/settings/embedder/ollama",
            "/v1/settings/llm",
            "/v1/settings/steward/cadence",
            "/v1/runtime/restart",
            "/v1/logs",
            // v0.10.2+ MCP Streamable HTTP transport:
            "/mcp",
        ] {
            assert!(
                paths.contains_key(expected),
                "openapi paths missing {expected}: {paths:?}"
            );
        }

        // Method coverage on /memory/documents: must document both POST
        // (ingest) and GET (list).
        let docs = paths.get("/memory/documents").expect("/memory/documents");
        assert!(
            docs.get("post").is_some(),
            "POST /memory/documents undocumented"
        );
        assert!(
            docs.get("get").is_some(),
            "GET /memory/documents undocumented"
        );

        // Method coverage on /memory/documents/{id}: must document both
        // GET (inspect) and DELETE (forget).
        let docid = paths
            .get("/memory/documents/{id}")
            .expect("/memory/documents/{id}");
        assert!(
            docid.get("get").is_some(),
            "GET /memory/documents/{{id}} undocumented"
        );
        assert!(
            docid.get("delete").is_some(),
            "DELETE /memory/documents/{{id}} undocumented"
        );

        // Method coverage on /memory/{id}: must document GET (inspect),
        // PATCH (update), and DELETE (forget).
        let memid = paths.get("/memory/{id}").expect("memory/{id}");
        assert!(
            memid.get("get").is_some(),
            "GET /memory/{{id}} undocumented"
        );
        assert!(
            memid.get("patch").is_some(),
            "PATCH /memory/{{id}} undocumented"
        );
        assert!(
            memid.get("delete").is_some(),
            "DELETE /memory/{{id}} undocumented"
        );

        // Component schemas referenced from paths must be defined.
        for schema_name in [
            "RememberRequest",
            "RememberResponse",
            "RecallRequest",
            "RecallResult",
            "MemoryContextRequest",
            "MemoryContextResult",
            "MemoryUpdateRequest",
            "MemoryUpdateResult",
            "EpisodeRecord",
            "ApiError",
            "ConsolidationScope",
            "ConsolidationReport",
            "TriplesExtractRequest",
            "TriplesExtractResponse",
            "DerivedRepairRequest",
            "DerivedRepairCandidate",
            "DerivedRepairReport",
            "MemoryQualityAuditReport",
            // Path 1 derived-layer schemas (v0.4.0+):
            "ThemeHit",
            "FactHit",
            "EntityHit",
            "EntityReviewOpReport",
            "ContradictionHit",
            "ContradictionResolveRequest",
            "ContradictionResolution",
            "ProjectDescriptor",
            "ProjectFactsRequest",
            "ProjectFactsResponse",
            "ProjectDecisionAddRequest",
            "ProjectDecisionAddResponse",
            "ProjectDecisionSearchRequest",
            "ProjectDecisionSearchResponse",
            "ProjectPolicyRequest",
            "ProjectPolicyResponse",
            // v0.5.0 Priority 3:
            "ClusterRecord",
            // v0.7.0 P6 — document schemas:
            "IngestDocumentRequest",
            "ImportDocumentsRequest",
            "DocumentUploadPrepareRequest",
            "DocumentUploadPrepareResponse",
            "DocumentUploadStatusResponse",
            "DocumentUploadAbortResponse",
            "DocumentUploadCommitRequest",
            "DocumentUploadCommitResponse",
            "StagedIngestRequest",
            "StagedIngestResponse",
            "NativeImportResponse",
            "NativeImportFile",
            "NativeImportResult",
            "IngestReport",
            "ForgetDocumentReport",
            "SearchDocsRequest",
            "DocSearchHit",
            "DocumentInspectResult",
            "DocumentSummary",
            // solo-web graph + Community schemas:
            "GraphNode",
            "GraphEdge",
            "GraphResponse",
            "GraphNodesResponse",
            "GraphEdgesResponse",
            "GraphRelationshipInspectResponse",
            "GraphPathStep",
            "GraphPath",
            "GraphPathsResponse",
            "GraphInspectResponse",
            "MemoryInboxItem",
            "MemoryInboxResponse",
            "MemoryInboxReviewRequest",
            "MemoryReviewReport",
            "LogTailLine",
            "LogsResponse",
            "StatusResponse",
            "StatusSteward",
            "StatusCapability",
            "StatusCapabilities",
            "DerivedCoverage",
            "StewardBackfillRequest",
            "StewardBackfillStatus",
            "StewardBackfillResponse",
            "OllamaEmbedderSwitchRequest",
            "OllamaEmbedderSwitchResponse",
            "SwitchLlmRequest",
            "LlmSettingsSummary",
            "SwitchLlmResponse",
            "StewardCadenceSettingsRequest",
            "StewardCadenceSettingsSummary",
            "StewardCadenceSettingsResponse",
            "RuntimeRestartResponse",
            // MCP HTTP JSON-RPC schemas:
            "JsonRpcRequest",
            "JsonRpcResponse",
        ] {
            let ptr = format!("/components/schemas/{schema_name}");
            assert!(
                spec.pointer(&ptr).is_some(),
                "component schema {schema_name} missing"
            );
        }

        let graph_edge_props = spec
            .pointer("/components/schemas/GraphEdge/properties")
            .and_then(|v| v.as_object())
            .expect("GraphEdge properties");
        assert!(
            graph_edge_props.contains_key("predicate"),
            "GraphEdge schema must expose the serialized predicate field"
        );
        assert!(
            !graph_edge_props.contains_key("label"),
            "GraphEdge schema must not document the obsolete label field"
        );

        let graph_nodes_limit = paths
            .get("/v1/graph/nodes")
            .and_then(|path| path.get("get"))
            .and_then(|get| get.get("parameters"))
            .and_then(|params| params.as_array())
            .and_then(|params| {
                params
                    .iter()
                    .find(|p| p.get("name").and_then(|v| v.as_str()) == Some("limit"))
            })
            .expect("/v1/graph/nodes limit parameter");
        assert_eq!(
            graph_nodes_limit
                .pointer("/schema/maximum")
                .and_then(|v| v.as_u64()),
            Some(GRAPH_NODES_MAX_LIMIT as u64),
            "OpenAPI graph-node limit maximum must match handler clamp"
        );
        assert_eq!(
            graph_nodes_limit
                .pointer("/schema/default")
                .and_then(|v| v.as_u64()),
            Some(GRAPH_NODES_DEFAULT_LIMIT as u64),
            "OpenAPI graph-node limit default must match handler default"
        );

        let graph_edges_limit = paths
            .get("/v1/graph/edges")
            .and_then(|path| path.get("get"))
            .and_then(|get| get.get("parameters"))
            .and_then(|params| params.as_array())
            .and_then(|params| {
                params
                    .iter()
                    .find(|p| p.get("name").and_then(|v| v.as_str()) == Some("limit"))
            })
            .expect("/v1/graph/edges limit parameter");
        assert_eq!(
            graph_edges_limit
                .pointer("/schema/maximum")
                .and_then(|v| v.as_u64()),
            Some(GRAPH_EDGES_MAX_LIMIT as u64),
            "OpenAPI graph-edge limit maximum must match handler clamp"
        );
        assert_eq!(
            graph_edges_limit
                .pointer("/schema/default")
                .and_then(|v| v.as_u64()),
            Some(GRAPH_EDGES_DEFAULT_LIMIT as u64),
            "OpenAPI graph-edge limit default must match handler default"
        );

        let mcp = paths.get("/mcp").expect("/mcp");
        assert!(mcp.get("post").is_some(), "POST /mcp undocumented");
        assert!(mcp.get("get").is_some(), "GET /mcp undocumented");

        assert!(
            !paths.contains_key("/v1/tenants"),
            "Community OpenAPI must not expose tenant management"
        );
        assert!(
            !paths.contains_key("/v1/settings/relay"),
            "Community OpenAPI must not expose paid Relay configuration"
        );
        assert!(
            !spec.to_string().contains("X-Solo-Tenant"),
            "Community OpenAPI must not advertise database selectors"
        );

        let status_path = paths.get("/v1/status").expect("/v1/status");
        let status_get = status_path.get("get").expect("GET /v1/status undocumented");
        assert_eq!(
            status_get.pointer("/responses/200/content/application~1json/schema/$ref"),
            Some(&json!("#/components/schemas/StatusResponse")),
            "GET /v1/status must return StatusResponse"
        );

        let switch_path = paths
            .get("/v1/settings/embedder/ollama")
            .expect("/v1/settings/embedder/ollama");
        let switch_post = switch_path
            .get("post")
            .expect("POST /v1/settings/embedder/ollama undocumented");
        assert_eq!(
            switch_post.pointer("/responses/200/content/application~1json/schema/$ref"),
            Some(&json!("#/components/schemas/OllamaEmbedderSwitchResponse")),
            "POST /v1/settings/embedder/ollama must return OllamaEmbedderSwitchResponse"
        );

        let llm_switch_path = paths.get("/v1/settings/llm").expect("/v1/settings/llm");
        let llm_switch_post = llm_switch_path
            .get("post")
            .expect("POST /v1/settings/llm undocumented");
        assert_eq!(
            llm_switch_post.pointer("/responses/200/content/application~1json/schema/$ref"),
            Some(&json!("#/components/schemas/SwitchLlmResponse")),
            "POST /v1/settings/llm must return SwitchLlmResponse"
        );

        let cadence_path = paths
            .get("/v1/settings/steward/cadence")
            .expect("/v1/settings/steward/cadence");
        let cadence_post = cadence_path
            .get("post")
            .expect("POST /v1/settings/steward/cadence undocumented");
        assert_eq!(
            cadence_post.pointer("/responses/200/content/application~1json/schema/$ref"),
            Some(&json!(
                "#/components/schemas/StewardCadenceSettingsResponse"
            )),
            "POST /v1/settings/steward/cadence must return StewardCadenceSettingsResponse"
        );

        let runtime_restart_path = paths
            .get("/v1/runtime/restart")
            .expect("/v1/runtime/restart");
        let runtime_restart_post = runtime_restart_path
            .get("post")
            .expect("POST /v1/runtime/restart undocumented");
        assert_eq!(
            runtime_restart_post.pointer("/responses/200/content/application~1json/schema/$ref"),
            Some(&json!("#/components/schemas/RuntimeRestartResponse")),
            "POST /v1/runtime/restart must return RuntimeRestartResponse"
        );

        let status_schema = spec
            .pointer("/components/schemas/StatusResponse")
            .expect("StatusResponse schema");
        for field in [
            "ok", "version", "build", "library", "embedder", "mcp", "steward", "runtime",
        ] {
            assert!(
                status_schema
                    .pointer("/required")
                    .and_then(|v| v.as_array())
                    .is_some_and(|required| required.iter().any(|v| v == field)),
                "StatusResponse missing required field {field}"
            );
        }
        for ptr in [
            "/properties/library/required",
            "/properties/build/required",
            "/properties/build/properties/version_with_build",
            "/properties/build/properties/git_sha_short",
            "/properties/embedder/required",
            "/properties/mcp/required",
            "/properties/steward/$ref",
            "/properties/runtime/required",
            "/properties/embedder/properties/dim/minimum",
            "/properties/embedder/properties/runtime/required",
            "/properties/embedder/properties/runtime/properties/running",
            "/properties/mcp/properties/sessions/minimum",
            "/properties/runtime/properties/pid/minimum",
        ] {
            assert!(
                status_schema.pointer(ptr).is_some(),
                "StatusResponse schema missing {ptr}"
            );
        }

        // bearerAuth security scheme is declared (LAN deployments need it).
        assert!(
            spec.pointer("/components/securitySchemes/bearerAuth")
                .is_some(),
            "bearerAuth security scheme missing"
        );

        h.shutdown(&runtime);
    }

    /// `/openapi.json` must remain unauthenticated even when bearer auth
    /// is enabled — the spec describes the API shape, not secrets, and
    /// codegen tooling shouldn't need a credential to fetch it.
    #[test]
    fn openapi_json_is_exempt_from_bearer_auth() {
        let runtime = rt();
        let h = Harness::new_with_auth(&runtime, Some("super-secret".into()));
        let r = h.router.clone();
        // No Authorization header → still 200 for /openapi.json.
        let (status, _body) = runtime.block_on(call(r, "GET", "/openapi.json", None));
        assert_eq!(status, StatusCode::OK);
        h.shutdown(&runtime);
    }

