    /// `POST /memory/consolidate` runs the cluster pass and returns
    /// the report as JSON. With an empty body, `ConsolidationScope`
    /// defaults to unbounded; with a non-empty body, the
    /// `window_days` field is honored. The Harness's writer is
    /// spawned without a Steward, so `abstractions_built` stays 0
    /// even when `clusters_built` is nonzero — same posture as the
    /// daemon today.
    #[test]
    fn consolidate_endpoint_returns_report() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        runtime.block_on(async move {
            // Empty DB → all-zero report; structural assertion only.
            let (status, body) = call(r.clone(), "POST", "/memory/consolidate", None).await;
            assert_eq!(status, StatusCode::OK);
            for field in [
                "episodes_seen",
                "clusters_built",
                "episodes_clustered",
                "abstractions_built",
                "triples_built",
                "contradictions_found",
            ] {
                assert!(
                    body.get(field).and_then(|v| v.as_u64()).is_some(),
                    "missing field {field}: {body}"
                );
            }
            assert_eq!(body["episodes_seen"], 0);
            assert_eq!(body["clusters_built"], 0);

            // Non-empty body with window_days → still 200; unmistakable
            // shape round-trips through ConsolidationScope's serde.
            let (status2, _body2) = call(
                r,
                "POST",
                "/memory/consolidate",
                Some(json!({ "window_days": 7 })),
            )
            .await;
            assert_eq!(status2, StatusCode::OK);
        });
        h.shutdown(&runtime);
    }

    #[test]
    fn triples_extract_endpoint_returns_skipped_report_without_steward() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        runtime.block_on(async move {
            let (status, body) = call(r.clone(), "POST", "/memory/triples/extract", None).await;
            assert_eq!(status, StatusCode::OK, "body: {body}");
            assert_eq!(body["ran"], false);
            assert_eq!(body["abstractions_built"], 0);
            assert_eq!(body["triples_extracted"], 0);
            assert_eq!(body["limit"], 50);
            assert!(
                body["note"]
                    .as_str()
                    .is_some_and(|note| note.contains("No Steward runtime")),
                "body: {body}"
            );

            let (status_status, status_body) = call(r.clone(), "GET", "/v1/status", None).await;
            assert_eq!(status_status, StatusCode::OK, "body: {status_body}");
            assert_eq!(
                status_body
                    .pointer("/steward/last_triples_trigger")
                    .and_then(|v| v.as_str()),
                Some("manual")
            );
            assert_eq!(
                status_body
                    .pointer("/steward/last_triples_batch/ran")
                    .and_then(|v| v.as_bool()),
                Some(false)
            );
            assert!(
                status_body
                    .pointer("/steward/last_triples_run_at_ms")
                    .and_then(|v| v.as_i64())
                    .is_some(),
                "status should record the skipped manual extraction time: {status_body}"
            );

            let (bad_status, bad_body) = call(
                r,
                "POST",
                "/memory/triples/extract",
                Some(json!({ "limit": 501 })),
            )
            .await;
            assert_eq!(bad_status, StatusCode::BAD_REQUEST, "body: {bad_body}");
        });
        h.shutdown(&runtime);
    }

