    #[test]
    fn entity_split_review_endpoint_records_op_and_revision() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let body = runtime.block_on(async move {
            let (status, body) = call(
                r,
                "POST",
                "/memory/entities/split-review",
                Some(json!({
                    "entity_id": "solo",
                    "affected_aliases": [" solo relay ", "solo relay", "Solo Desktop"],
                    "reason": "separate related products"
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "body: {body}");
            assert_eq!(body["op_kind"], "split");
            assert_eq!(body["status"], "needs_review");
            assert_eq!(body["source_entity_id"], "solo");
            assert_eq!(body["target_entity_id"], Value::Null);
            assert_eq!(
                body["affected_aliases"],
                json!(["solo relay", "Solo Desktop"])
            );
            body
        });

        let op_id = body["op_id"].as_str().expect("op_id").to_string();
        let conn = h.open_db();
        let (op_count, revision_count): (i64, i64) = conn
            .query_row(
                "SELECT
                    (SELECT COUNT(*) FROM entity_review_ops WHERE op_id = ?1 AND op_kind = 'split'),
                    (SELECT COUNT(*) FROM memory_revisions
                      WHERE revision_kind = 'entity_split_requested'
                        AND target_kind = 'entity'
                        AND previous_id = 'solo'
                        AND metadata_json LIKE '%' || ?1 || '%')",
                rusqlite::params![op_id],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(op_count, 1);
        assert_eq!(revision_count, 1);
        h.shutdown(&runtime);
    }

    #[test]
    fn memory_quality_review_endpoint_updates_status() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let review_id = MemoryId::new().to_string();
        let now_ms = chrono::Utc::now().timestamp_millis();
        {
            let conn = h.open_db();
            conn.execute(
                "INSERT INTO triple_reviews
                    (review_id, candidate_fingerprint, subject_id, predicate,
                     object_id, object_kind, confidence, reason_code, reason,
                     provenance_json, status, created_at_ms, updated_at_ms)
                 VALUES
                    (?1, 'fp-http-review-update', 'assistant', 'said',
                     'unable to help', 'literal', 0.4, 'assistant_or_tool_chatter',
                     'not durable user memory', '{}', 'needs_review', ?2, ?2)",
                rusqlite::params![&review_id, now_ms],
            )
            .expect("seed review");
        }

        let r = h.router.clone();
        let review_id_for_db = review_id.clone();
        runtime.block_on(async move {
            let (list_status, list_body) = call(
                r.clone(),
                "GET",
                "/memory/quality/reviews?status=needs_review",
                None,
            )
            .await;
            assert_eq!(list_status, StatusCode::OK, "body: {list_body}");
            assert_eq!(list_body["items"].as_array().unwrap().len(), 1);

            let (status, body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{review_id}"),
                Some(json!({ "status": "dismissed", "note": "not durable" })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "body: {body}");
            assert_eq!(body["status"], "dismissed");
            assert_eq!(body["claim_status"], "rejected");
            assert!(body["claim_id"].as_str().is_some());
            assert!(body["quality_score"].as_f64().is_some());
            assert!(
                body["claim_reason_codes"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|code| code.as_str() == Some("user_rejected")),
                "dismissed review should mark claim reason: {body}"
            );

            let (empty_status, empty_body) = call(
                r.clone(),
                "GET",
                "/memory/quality/reviews?status=needs_review",
                None,
            )
            .await;
            assert_eq!(empty_status, StatusCode::OK, "body: {empty_body}");
            assert_eq!(empty_body["items"].as_array().unwrap().len(), 0);

            let (bad_status, bad_body) = call(
                r,
                "POST",
                &format!("/memory/quality/reviews/{review_id}"),
                Some(json!({ "status": "active_fact" })),
            )
            .await;
            assert_eq!(bad_status, StatusCode::BAD_REQUEST, "body: {bad_body}");
        });
        let conn = h.open_db();
        let revision_count: i64 = conn
            .query_row(
                "SELECT COUNT(*)
                   FROM memory_revisions
                  WHERE revision_kind = 'claim_rejected'
                    AND previous_id = ?1",
                rusqlite::params![review_id_for_db],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(revision_count, 1);
        h.shutdown(&runtime);
    }

