    #[test]
    fn memory_quality_review_endpoint_promotes_and_rewrites_facts() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let approve_review_id = MemoryId::new().to_string();
        let approve_triple_id = MemoryId::new().to_string();
        let rewrite_review_id = MemoryId::new().to_string();
        let bad_rewrite_review_id = MemoryId::new().to_string();
        let now_ms = chrono::Utc::now().timestamp_millis();
        {
            let conn = h.open_db();
            conn.execute(
                "INSERT INTO entities
                    (entity_id, canonical_name, entity_type, aliases_json, confidence,
                     first_seen_ms, last_seen_ms, status, created_at_ms, updated_at_ms)
                 VALUES
                    ('solo', 'Solo', 'project', '[]', 1.0, ?1, ?1, 'active', ?1, ?1),
                    ('ollama', 'Ollama', 'tool', '[]', 1.0, ?1, ?1, 'active', ?1, ?1)",
                rusqlite::params![now_ms],
            )
            .expect("seed approve entities");
            conn.execute(
                "INSERT INTO triples
                    (triple_id, subject_id, predicate, object_id, object_kind,
                     valid_from_ms, valid_to_ms, confidence, provenance_json,
                     status, created_at_ms, updated_at_ms)
                 VALUES
                    (?1, 'solo', 'uses', 'ollama', 'entity',
                     ?2, NULL, 0.20, '{}', 'superseded', ?2, ?2)",
                rusqlite::params![&approve_triple_id, now_ms],
            )
            .expect("seed stale approve triple");
            conn.execute(
                "INSERT INTO relationship_edges
                    (edge_id, subject_entity_id, predicate, object_entity_id, object_literal,
                     object_kind, valid_from_ms, valid_to_ms, confidence, strength,
                     evidence_count, status, created_at_ms, updated_at_ms)
                 VALUES
                    (?1, 'solo', 'uses', 'ollama', NULL, 'entity',
                     ?2, NULL, 0.20, 0.20, 0, 'superseded', ?2, ?2)",
                rusqlite::params![&approve_triple_id, now_ms],
            )
            .expect("seed stale approve edge");
            conn.execute(
                "INSERT INTO triple_reviews
                    (review_id, candidate_fingerprint, triple_id, subject_id, predicate,
                     object_id, object_kind, confidence, reason_code, reason,
                     provenance_json, status, created_at_ms, updated_at_ms)
                 VALUES
                    (?1, 'fp-http-review-approve', ?2, 'solo', 'uses',
                     'ollama', 'entity', 0.92, 'operator_approved',
                     'operator approved durable project fact', '{}', 'needs_review', ?3, ?3)",
                rusqlite::params![&approve_review_id, &approve_triple_id, now_ms],
            )
            .expect("seed approve review");
            conn.execute(
                "INSERT INTO triple_reviews
                    (review_id, candidate_fingerprint, subject_id, predicate,
                     object_id, object_kind, confidence, reason_code, reason,
                     provenance_json, status, created_at_ms, updated_at_ms)
                 VALUES
                    (?1, 'fp-http-review-rewrite', 'solo', 'has',
                     'long noisy blob', 'literal', 0.7, 'weak_literal_claim',
                     'needs a cleaner fact', '{}', 'needs_review', ?2, ?2)",
                rusqlite::params![&rewrite_review_id, now_ms],
            )
            .expect("seed rewrite review");
            conn.execute(
                "INSERT INTO triple_reviews
                    (review_id, candidate_fingerprint, subject_id, predicate,
                     object_id, object_kind, confidence, reason_code, reason,
                     provenance_json, status, created_at_ms, updated_at_ms)
                 VALUES
                    (?1, 'fp-http-review-bad-rewrite', 'solo', 'has',
                     'bad replacement', 'literal', 0.7, 'weak_literal_claim',
                     'needs a cleaner fact', '{}', 'needs_review', ?2, ?2)",
                rusqlite::params![&bad_rewrite_review_id, now_ms],
            )
            .expect("seed bad rewrite review");
        }

        let r = h.router.clone();
        runtime.block_on(async move {
            let (approve_status, approve_body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{approve_review_id}"),
                Some(json!({ "status": "approved", "note": "good fact" })),
            )
            .await;
            assert_eq!(approve_status, StatusCode::OK, "body: {approve_body}");
            assert_eq!(approve_body["status"], "approved");
            assert_eq!(approve_body["claim_status"], "active");
            assert!(
                approve_body["claim_reason_codes"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|code| code.as_str() == Some("user_approved")),
                "approved review should mark claim reason: {approve_body}"
            );

            let (rewrite_status, rewrite_body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{rewrite_review_id}"),
                Some(json!({
                    "status": "rewritten",
                    "note": "split into clean facts",
                    "rewrites": [
                        {
                            "subject_id": "solo",
                            "predicate": "uses",
                            "object_id": "ollama",
                            "object_kind": "entity",
                            "confidence": 0.95
                        },
                        {
                            "subject_id": "solo",
                            "predicate": "has_status",
                            "object_id": "graph_quality_improving",
                            "object_kind": "literal"
                        }
                    ]
                })),
            )
            .await;
            assert_eq!(rewrite_status, StatusCode::OK, "body: {rewrite_body}");
            assert_eq!(rewrite_body["status"], "rewritten");
            assert_eq!(rewrite_body["claim_status"], "superseded");

            let (retry_status, retry_body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{rewrite_review_id}"),
                Some(json!({ "status": "rewritten" })),
            )
            .await;
            assert_eq!(retry_status, StatusCode::OK, "body: {retry_body}");
            assert_eq!(retry_body["status"], "rewritten");

            let (approved_dismiss_status, approved_dismiss_body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{approve_review_id}"),
                Some(json!({ "status": "dismissed", "note": "changed my mind" })),
            )
            .await;
            assert_eq!(
                approved_dismiss_status,
                StatusCode::BAD_REQUEST,
                "body: {approved_dismiss_body}"
            );

            let (rewritten_dismiss_status, rewritten_dismiss_body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{rewrite_review_id}"),
                Some(json!({ "status": "dismissed", "note": "changed my mind" })),
            )
            .await;
            assert_eq!(
                rewritten_dismiss_status,
                StatusCode::BAD_REQUEST,
                "body: {rewritten_dismiss_body}"
            );

            let (low_conf_status, low_conf_body) = call(
                r.clone(),
                "POST",
                &format!("/memory/quality/reviews/{bad_rewrite_review_id}"),
                Some(json!({
                    "status": "rewritten",
                    "rewrites": [
                        {
                            "subject_id": "solo",
                            "predicate": "uses",
                            "object_id": "ollama",
                            "object_kind": "entity",
                            "confidence": 0.1
                        }
                    ]
                })),
            )
            .await;
            assert_eq!(
                low_conf_status,
                StatusCode::BAD_REQUEST,
                "body: {low_conf_body}"
            );

            let (empty_canonical_status, empty_canonical_body) = call(
                r,
                "POST",
                &format!("/memory/quality/reviews/{bad_rewrite_review_id}"),
                Some(json!({
                    "status": "rewritten",
                    "rewrites": [
                        {
                            "subject_id": "!!!",
                            "predicate": "uses",
                            "object_id": "ollama",
                            "object_kind": "entity",
                            "confidence": 0.95
                        }
                    ]
                })),
            )
            .await;
            assert_eq!(
                empty_canonical_status,
                StatusCode::BAD_REQUEST,
                "body: {empty_canonical_body}"
            );
        });

        let conn = h.open_db();
        let approved_active: i64 = conn
            .query_row(
                "SELECT COUNT(*)
                   FROM triples
                  WHERE triple_id = ?1
                    AND subject_id = 'solo'
                    AND predicate = 'uses'
                    AND object_id = 'ollama'
                    AND object_kind = 'entity'
                    AND status = 'active'",
                rusqlite::params![approve_triple_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(approved_active, 1);
        let approved_edge: (String, String, String, f32, f32, i64, String) = conn
            .query_row(
                "SELECT subject_entity_id, predicate, object_entity_id,
                        confidence, strength, evidence_count, status
                   FROM relationship_edges
                  WHERE edge_id = ?1",
                rusqlite::params![&approve_triple_id],
                |r| {
                    Ok((
                        r.get(0)?,
                        r.get(1)?,
                        r.get(2)?,
                        r.get(3)?,
                        r.get(4)?,
                        r.get(5)?,
                        r.get(6)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            approved_edge,
            (
                "solo".into(),
                "uses".into(),
                "ollama".into(),
                0.92,
                0.92,
                1,
                "active".into()
            )
        );
        let rewritten_count: i64 = conn
            .query_row(
                "SELECT COUNT(*)
                   FROM triples
                  WHERE subject_id = 'solo'
                    AND predicate IN ('uses', 'has_status')
                    AND status = 'active'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(
            rewritten_count >= 2,
            "rewrite should create active clean facts"
        );
        let status_rewrite_count: i64 = conn
            .query_row(
                "SELECT COUNT(*)
                   FROM triples
                  WHERE subject_id = 'solo'
                    AND predicate = 'has_status'
                    AND object_id = 'graph_quality_improving'
                    AND status = 'active'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            status_rewrite_count, 1,
            "retrying a rewritten review should not duplicate replacement facts"
        );
        let edge_count: i64 = conn
            .query_row(
                "SELECT COUNT(*)
                   FROM relationship_edges
                  WHERE subject_entity_id = 'solo'
                    AND status = 'active'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(edge_count >= 2, "active facts should have graph edges");
        let revision_count: i64 = conn
            .query_row(
                "SELECT COUNT(*)
                   FROM memory_revisions
                  WHERE revision_kind IN ('claim_activated', 'claim_rewritten')",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(revision_count, 2);
        h.shutdown(&runtime);
    }

    #[test]
    fn auth_required_routes_reject_missing_token() {
        let runtime = rt();
        let h = Harness::new_with_auth(&runtime, Some("secret-xyz".into()));
        let r = h.router.clone();
        runtime.block_on(async move {
            // No Authorization header → 401.
            let (status, _body) = call(
                r.clone(),
                "POST",
                "/memory",
                Some(json!({ "content": "x" })),
            )
            .await;
            assert_eq!(status, StatusCode::UNAUTHORIZED);

            // Wrong token → 401.
            let (status, _body) = call_with_auth(
                r.clone(),
                "POST",
                "/memory",
                Some(json!({ "content": "x" })),
                Some("Bearer wrong-token"),
            )
            .await;
            assert_eq!(status, StatusCode::UNAUTHORIZED);

            // Correct token → handler runs (200).
            let (status, body) = call_with_auth(
                r.clone(),
                "POST",
                "/memory",
                Some(json!({ "content": "authed" })),
                Some("Bearer secret-xyz"),
            )
            .await;
            assert_eq!(status, StatusCode::OK);
            assert!(body.get("memory_id").is_some());
        });
        h.shutdown(&runtime);
    }

