    #[test]
    fn project_decision_endpoints_store_and_filter_structured_scope() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let project = json!({
            "name": "Solo",
            "id": "solo",
            "root": "C:\\Users\\Example\\Projects\\solo-community",
            "tags": ["memory"]
        });
        let other_project = json!({
            "name": "Other",
            "id": "other",
            "root": "C:\\tmp\\other",
            "tags": []
        });

        let r = h.router.clone();
        let (status, body) = runtime.block_on(call(
            r.clone(),
            "POST",
            "/v1/project/decisions",
            Some(json!({
                "project": project.clone(),
                "decision": "Use daemon HTTP endpoints for Desktop project memory."
            })),
        ));
        assert_eq!(
            status,
            StatusCode::OK,
            "project decision add failed: {body}"
        );
        assert_eq!(body["command"], "project decisions");
        assert_eq!(body["action"], "add");
        assert_eq!(body["source_type"], "project_decision");
        assert!(
            body["source_id"]
                .as_str()
                .is_some_and(|value| value.starts_with("project:solo:decision:")),
            "unexpected source id: {body}"
        );

        let (status, body) = runtime.block_on(call(
            r.clone(),
            "POST",
            "/v1/project/decisions",
            Some(json!({
                "project": other_project,
                "decision": "Use daemon HTTP endpoints for Desktop project memory."
            })),
        ));
        assert_eq!(
            status,
            StatusCode::OK,
            "decoy project decision add failed: {body}"
        );

        let (status, body) = runtime.block_on(call(
            r,
            "POST",
            "/v1/project/decisions/search",
            Some(json!({
                "project": project,
                "query": "daemon HTTP endpoints",
                "limit": 10
            })),
        ));
        assert_eq!(
            status,
            StatusCode::OK,
            "project decision search failed: {body}"
        );
        assert_eq!(body["command"], "project decisions");
        assert_eq!(body["action"], "query");
        assert_eq!(body["project"]["id"], "solo");
        let hits = body["hits"].as_array().expect("hits array");
        assert_eq!(hits.len(), 1, "expected only the solo decision, got {body}");
        assert_eq!(hits[0]["source_type"], "project_decision");
        assert!(
            hits[0]["content"]
                .as_str()
                .is_some_and(|value| value.contains("(id: solo,")),
            "expected scoped project content, got {body}"
        );
        h.shutdown(&runtime);
    }

