    #[test]
    fn document_ingest_rejects_path_outside_workspace_file_access_roots() {
        let runtime = rt();
        let allowed = tempfile::TempDir::new().unwrap();
        let outside = tempfile::TempDir::new().unwrap();
        let outside_file = outside.path().join("outside.md");
        std::fs::write(&outside_file, "outside").unwrap();
        let policy = crate::WorkspaceFileAccessPolicy::restricted_to_roots(vec![
            allowed.path().to_path_buf(),
        ])
        .expect("policy");
        let h = Harness::new_with_workspace_file_access(&runtime, policy);
        let (status, body) = runtime.block_on(call(
            h.router.clone(),
            "POST",
            "/memory/documents",
            Some(json!({ "path": outside_file.display().to_string() })),
        ));
        assert_eq!(status, StatusCode::FORBIDDEN, "expected 403, got {body}");
        assert!(
            body["error"]
                .as_str()
                .is_some_and(|error| error.contains("workspace_file_access.allowed_roots")),
            "expected workspace policy error, got {body}"
        );
        h.shutdown(&runtime);
    }

