    #[test]
    fn import_documents_endpoint_source_filters_native_dry_run() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let dir = h._tmp.path().join("source-filter-docs");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("a.md"), "# A\nbody").unwrap();
        std::fs::write(dir.join("b.txt"), "body").unwrap();

        let r = h.router.clone();
        let (status, body) = runtime.block_on(call(
            r,
            "POST",
            "/memory/documents/import",
            Some(json!({
                "path": dir.display().to_string(),
                "source": "markdown",
                "dry_run": true,
                "max_files": 10
            })),
        ));
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            body.get("source").and_then(|v| v.as_str()),
            Some("markdown")
        );
        assert_eq!(
            body.get("source_label").and_then(|v| v.as_str()),
            Some("Markdown")
        );
        assert_eq!(body.get("total_files").and_then(|v| v.as_u64()), Some(1));
        let files = body.get("files").and_then(|v| v.as_array()).expect("files");
        assert!(
            files[0]
                .get("path")
                .and_then(|v| v.as_str())
                .is_some_and(|path| path.ends_with("a.md")),
            "expected markdown file only, got {body}"
        );

        let (status, body) = runtime.block_on(call(
            h.router.clone(),
            "POST",
            "/memory/documents/import",
            Some(json!({
                "path": dir.display().to_string(),
                "source": "markdown_text",
                "dry_run": true,
                "max_files": 10
            })),
        ));
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            body.get("source").and_then(|v| v.as_str()),
            Some("markdown_text")
        );
        assert_eq!(
            body.get("source_label").and_then(|v| v.as_str()),
            Some("Markdown/Text")
        );
        assert_eq!(body.get("total_files").and_then(|v| v.as_u64()), Some(2));
        let mut paths = body
            .get("files")
            .and_then(|v| v.as_array())
            .expect("files")
            .iter()
            .filter_map(|file| file.get("path").and_then(|v| v.as_str()))
            .map(str::to_owned)
            .collect::<Vec<_>>();
        paths.sort();
        assert!(
            paths.iter().any(|path| path.ends_with("a.md"))
                && paths.iter().any(|path| path.ends_with("b.txt")),
            "expected markdown and text files, got {body}"
        );
        h.shutdown(&runtime);
    }

    #[test]
    fn import_documents_endpoint_stores_original_assets_when_requested() {
        let runtime = rt();
        let h = Harness::new_with_embedder(&runtime);
        let dir = h._tmp.path().join("asset-import-docs");
        std::fs::create_dir_all(&dir).unwrap();
        let file_path = dir.join("source.md");
        let bytes = b"# Source\n\nretain this exact file";
        std::fs::write(&file_path, bytes).unwrap();

        let r = h.router.clone();
        let asset_root = h._tmp.path().to_path_buf();
        let (status, body) = runtime.block_on(call(
            r,
            "POST",
            "/memory/documents/import",
            Some(json!({
                "path": dir.display().to_string(),
                "dry_run": false,
                "max_files": 10,
                "store_original_file": true
            })),
        ));
        assert_eq!(status, StatusCode::OK, "body: {body}");
        assert_eq!(
            body.get("store_original_file").and_then(|v| v.as_bool()),
            Some(true)
        );
        assert_eq!(body.get("imported").and_then(|v| v.as_u64()), Some(1));
        assert_eq!(
            body.get("assets_retained").and_then(|v| v.as_u64()),
            Some(1)
        );
        assert_eq!(body.get("assets_deduped").and_then(|v| v.as_u64()), Some(0));
        assert_eq!(body.get("asset_links").and_then(|v| v.as_u64()), Some(1));
        assert_eq!(body.get("asset_failed").and_then(|v| v.as_u64()), Some(0));
        let result = body
            .pointer("/results/0")
            .and_then(|v| v.as_object())
            .unwrap_or_else(|| panic!("missing first import result: {body}"));
        let asset = result
            .get("asset")
            .and_then(|v| v.as_object())
            .unwrap_or_else(|| panic!("missing retained asset: {body}"));
        let link = result
            .get("document_asset_link")
            .and_then(|v| v.as_object())
            .unwrap_or_else(|| panic!("missing document asset link: {body}"));
        assert_eq!(
            asset.get("filename").and_then(|v| v.as_str()),
            Some("source.md")
        );
        assert_eq!(
            asset.get("mime_type").and_then(|v| v.as_str()),
            Some("text/markdown")
        );
        assert_eq!(
            asset.get("size_bytes").and_then(|v| v.as_u64()),
            Some(bytes.len() as u64)
        );
        assert_eq!(
            link.get("relation_type").and_then(|v| v.as_str()),
            Some("source_import")
        );
        assert_eq!(
            link.get("doc_id").and_then(|v| v.as_str()),
            result.get("doc_id").and_then(|v| v.as_str())
        );
        assert_eq!(
            link.get("asset_id").and_then(|v| v.as_str()),
            asset.get("asset_id").and_then(|v| v.as_str())
        );
        let storage_path = asset
            .get("storage_path")
            .and_then(|v| v.as_str())
            .expect("asset storage_path");
        assert!(
            asset_root.join(storage_path).is_file(),
            "retained original file should exist in the asset store"
        );
        assert!(
            result.get("asset_error").is_none(),
            "asset retention should not report an error: {body}"
        );
        h.shutdown(&runtime);
    }

    #[test]
    fn document_upload_roundtrip_ingests_stores_original_and_deletes_staged_source() {
        let runtime = rt();
        let h = Harness::new_with_embedder(&runtime);
        let r = h.router.clone();
        let data_dir = h.registry.data_dir().to_path_buf();
        let asset_root = h._tmp.path().to_path_buf();
        runtime.block_on(async {
            let bytes = b"# Uploaded\n\nhello staged upload".to_vec();
            let (status, prepared) = call(
                r.clone(),
                "POST",
                "/memory/documents/uploads",
                Some(json!({
                    "filename": "uploaded.md",
                    "mime_type": "text/markdown",
                    "size_bytes": bytes.len()
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "prepare body: {prepared}");
            assert_eq!(
                prepared
                    .get("default_store_original_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            let upload_id = prepared
                .get("upload_id")
                .and_then(|v| v.as_str())
                .expect("upload_id")
                .to_string();
            let upload_url = prepared
                .get("upload_url")
                .and_then(|v| v.as_str())
                .expect("upload_url")
                .to_string();

            let req = Request::builder()
                .method("PATCH")
                .uri(upload_url)
                .header("content-type", "application/octet-stream")
                .header(crate::document_upload::UPLOAD_OFFSET_HEADER, "0")
                .header(
                    crate::document_upload::UPLOAD_LENGTH_HEADER,
                    bytes.len().to_string(),
                )
                .body(Body::from(bytes.clone()))
                .unwrap();
            let resp = r.clone().oneshot(req).await.expect("patch upload");
            assert_eq!(resp.status(), StatusCode::NO_CONTENT);
            let next = resp
                .headers()
                .get(crate::document_upload::UPLOAD_OFFSET_HEADER)
                .and_then(|v| v.to_str().ok())
                .map(str::to_string);
            assert_eq!(next, Some(bytes.len().to_string()));
            let _ = resp.into_body().collect().await.unwrap();

            let (status, upload_status) = call(
                r.clone(),
                "GET",
                &format!("/memory/documents/uploads/{upload_id}"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "status body: {upload_status}");
            assert_eq!(
                upload_status.get("bytes_received").and_then(|v| v.as_u64()),
                Some(bytes.len() as u64)
            );

            let (status, committed) = call(
                r.clone(),
                "POST",
                &format!("/memory/documents/uploads/{upload_id}/commit"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "commit body: {committed}");
            let staged_uri = committed
                .get("staged_uri")
                .and_then(|v| v.as_str())
                .expect("staged_uri")
                .to_string();
            let staged_path = crate::document_upload::staged_path_for_tests(&data_dir, &staged_uri)
                .expect("staged path");
            assert_eq!(
                staged_path.file_name().and_then(|name| name.to_str()),
                Some("uploaded.md"),
                "staged path should preserve the user-facing filename"
            );
            let staged_dir = staged_path
                .parent()
                .expect("staged file has upload dir")
                .to_path_buf();
            assert!(
                staged_path.is_file(),
                "staged file should exist before ingest"
            );

            let (status, ingested) = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(json!({
                    "staged_uri": staged_uri
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "ingest body: {ingested}");
            assert_eq!(
                ingested
                    .get("stored_original_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            let asset = ingested
                .get("asset")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing persisted asset: {ingested}"));
            let link = ingested
                .get("document_asset_link")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing document asset link: {ingested}"));
            assert_eq!(
                asset.get("filename").and_then(|v| v.as_str()),
                Some("uploaded.md")
            );
            assert_eq!(
                asset.get("mime_type").and_then(|v| v.as_str()),
                Some("text/markdown")
            );
            assert_eq!(
                asset.get("size_bytes").and_then(|v| v.as_u64()),
                Some(bytes.len() as u64)
            );
            assert_eq!(
                link.get("asset_id").and_then(|v| v.as_str()),
                asset.get("asset_id").and_then(|v| v.as_str())
            );
            assert_eq!(
                link.get("doc_id").and_then(|v| v.as_str()),
                ingested.get("document_id").and_then(|v| v.as_str())
            );
            assert_eq!(
                link.get("relation_type").and_then(|v| v.as_str()),
                Some("source_upload")
            );
            let storage_path = asset
                .get("storage_path")
                .and_then(|v| v.as_str())
                .expect("asset storage_path");
            assert!(
                asset_root.join(storage_path).is_file(),
                "persistent original file should exist in the tenant asset store"
            );
            let asset_id = asset
                .get("asset_id")
                .and_then(|v| v.as_str())
                .expect("asset_id")
                .to_string();
            assert_eq!(
                ingested
                    .get("deleted_staged_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            assert!(
                !staged_path.exists(),
                "staged source file should be deleted after ingest"
            );
            assert!(
                !staged_dir.exists(),
                "empty per-upload staging dir should be removed after ingest"
            );
            assert_eq!(
                ingested.get("deduped").and_then(|v| v.as_bool()),
                Some(false)
            );
            let document_id = ingested
                .get("document_id")
                .and_then(|v| v.as_str())
                .expect("document_id")
                .to_string();
            let (status, inspected_doc) = call(
                r.clone(),
                "GET",
                &format!("/memory/documents/{document_id}"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "inspect body: {inspected_doc}");
            assert_eq!(
                inspected_doc
                    .pointer("/linked_assets/0/asset_id")
                    .and_then(|v| v.as_str()),
                Some(asset_id.as_str())
            );

            let (status, contract) = call(
                r.clone(),
                "POST",
                &format!("/memory/assets/{asset_id}/download-contract"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "download contract: {contract}");
            assert_eq!(
                contract.get("download_method").and_then(|v| v.as_str()),
                Some("GET")
            );
            assert_eq!(
                contract.get("sha256").and_then(|v| v.as_str()),
                asset.get("sha256").and_then(|v| v.as_str())
            );
            assert_eq!(
                contract.get("expires_at_ms"),
                Some(&Value::Null),
                "direct local download contracts should not claim a scoped token expiry"
            );
            let (status, legacy_contract) = call(
                r.clone(),
                "POST",
                &format!("/memory/assets/{asset_id}/download-token"),
                None,
            )
            .await;
            assert_eq!(
                status,
                StatusCode::OK,
                "legacy download-token alias: {legacy_contract}"
            );
            assert_eq!(legacy_contract, contract);
            let download_url = contract
                .get("download_url")
                .and_then(|v| v.as_str())
                .expect("download_url")
                .to_string();
            let resp = r
                .clone()
                .oneshot(
                    Request::builder()
                        .method("GET")
                        .uri(download_url)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .expect("download asset");
            assert_eq!(resp.status(), StatusCode::OK);
            assert_eq!(
                resp.headers()
                    .get(axum::http::header::CONTENT_TYPE)
                    .and_then(|v| v.to_str().ok()),
                Some("text/markdown")
            );
            assert_eq!(
                resp.headers()
                    .get(axum::http::header::CONTENT_DISPOSITION)
                    .and_then(|v| v.to_str().ok()),
                Some("attachment; filename=\"uploaded.md\"")
            );
            let downloaded = resp.into_body().collect().await.unwrap().to_bytes();
            assert_eq!(downloaded.as_ref(), bytes.as_slice());

            let (status, hits) = call(
                r.clone(),
                "POST",
                "/memory/documents/search",
                Some(json!({
                    "query": "hello staged upload",
                    "limit": 5
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "search body: {hits}");
            assert!(
                hits.as_array().is_some_and(|hits| hits
                    .iter()
                    .any(|hit| hit.get("doc_id").and_then(|v| v.as_str())
                        == Some(document_id.as_str()))),
                "ingested staged document should be searchable, got {hits}"
            );
        });
        drop(r);
        h.shutdown(&runtime);
    }

