    #[test]
    fn document_upload_textless_pdf_retains_asset_as_stored_unparsed() {
        let runtime = rt();
        let h = Harness::new_with_embedder(&runtime);
        let r = h.router.clone();
        let asset_id = runtime.block_on(async {
            let bytes = minimal_blank_pdf();
            let ingested = upload_and_ingest_staged_document(
                r.clone(),
                "scan.pdf",
                "application/pdf",
                bytes.clone(),
            )
            .await;
            assert_eq!(ingested.get("document_id"), Some(&Value::Null));
            assert_eq!(ingested.get("report"), Some(&Value::Null));
            assert_eq!(
                ingested.get("extraction_status").and_then(|v| v.as_str()),
                Some("stored_unparsed"),
                "textless PDF should retain original and report OCR gap: {ingested}"
            );
            assert!(
                ingested
                    .get("extraction_error")
                    .and_then(|v| v.as_str())
                    .is_some_and(|err| {
                        err.contains("no extractable text") && err.contains("OCR/page rendering")
                    }),
                "unexpected textless PDF extraction error: {ingested}"
            );

            let asset = ingested
                .get("asset")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing retained PDF asset: {ingested}"));
            assert_eq!(
                asset.get("filename").and_then(|v| v.as_str()),
                Some("scan.pdf")
            );
            assert_eq!(
                asset.get("mime_type").and_then(|v| v.as_str()),
                Some("application/pdf")
            );
            assert_eq!(
                asset.get("size_bytes").and_then(|v| v.as_u64()),
                Some(bytes.len() as u64)
            );
            let asset_id = asset
                .get("asset_id")
                .and_then(|v| v.as_str())
                .expect("asset_id")
                .to_string();

            let extraction = ingested
                .get("extraction")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing PDF extraction report: {ingested}"));
            assert_eq!(
                extraction.get("extractor_name").and_then(|v| v.as_str()),
                Some("pdf_text")
            );
            assert_eq!(
                extraction.get("status").and_then(|v| v.as_str()),
                Some("stored_unparsed")
            );

            let resp = r
                .clone()
                .oneshot(
                    Request::builder()
                        .method("GET")
                        .uri(format!("/memory/assets/{asset_id}/download"))
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .expect("download retained textless PDF asset");
            assert_eq!(resp.status(), StatusCode::OK);
            let downloaded = resp.into_body().collect().await.unwrap().to_bytes();
            assert_eq!(downloaded.as_ref(), bytes.as_slice());

            let (status, hits) = call(
                r.clone(),
                "POST",
                "/memory/documents/search",
                Some(json!({
                    "query": "scan",
                    "limit": 5
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "search body: {hits}");
            assert_eq!(
                hits.as_array().map(Vec::len),
                Some(0),
                "textless PDF should not create searchable chunks: {hits}"
            );

            asset_id
        });

        let (extractor_name, status, error): (String, String, Option<String>) = h
            .open_db()
            .query_row(
                "SELECT extractor_name, status, error FROM asset_extractions WHERE asset_id = ?1",
                rusqlite::params![asset_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("textless PDF extraction row");
        assert_eq!(extractor_name, "pdf_text");
        assert_eq!(status, "stored_unparsed");
        assert!(
            error
                .as_deref()
                .is_some_and(|err| err.contains("OCR/page rendering")),
            "unexpected stored PDF extraction error: {error:?}"
        );

        drop(r);
        h.shutdown(&runtime);
    }

