    #[test]
    fn document_upload_unsafe_zip_retains_asset_and_records_failed_extraction() {
        let runtime = rt();
        let h = Harness::new_with_embedder(&runtime);
        let r = h.router.clone();
        let asset_id = runtime.block_on(async {
            let bytes = stored_zip(&[("../evil.txt", "should stay inside retained bytes only")]);
            let ingested = upload_and_ingest_staged_document(
                r.clone(),
                "unsafe.zip",
                "application/zip",
                bytes.clone(),
            )
            .await;

            assert_eq!(ingested.get("document_id"), Some(&Value::Null));
            assert_eq!(ingested.get("report"), Some(&Value::Null));
            assert_eq!(
                ingested
                    .get("stored_original_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            assert_eq!(
                ingested.get("extraction_status").and_then(|v| v.as_str()),
                Some("failed")
            );
            assert_eq!(
                ingested.get("chunks_persisted").and_then(|v| v.as_u64()),
                Some(0)
            );
            assert!(
                ingested
                    .get("extraction_error")
                    .and_then(|v| v.as_str())
                    .is_some_and(|err| err.contains("unsafe path")),
                "unexpected unsafe ZIP extraction error: {ingested}"
            );

            let asset = ingested
                .get("asset")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing retained ZIP asset: {ingested}"));
            assert_eq!(
                asset.get("filename").and_then(|v| v.as_str()),
                Some("unsafe.zip")
            );
            assert_eq!(
                asset.get("mime_type").and_then(|v| v.as_str()),
                Some("application/zip")
            );
            assert_eq!(
                asset.get("size_bytes").and_then(|v| v.as_u64()),
                Some(bytes.len() as u64)
            );
            let asset_id = asset
                .get("asset_id")
                .and_then(|v| v.as_str())
                .expect("asset_id")
                .to_string();

            let extraction = ingested
                .get("extraction")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing failed ZIP extraction report: {ingested}"));
            assert_eq!(
                extraction.get("asset_id").and_then(|v| v.as_str()),
                Some(asset_id.as_str())
            );
            assert_eq!(
                extraction.get("extractor_name").and_then(|v| v.as_str()),
                Some("zip_manifest")
            );
            assert_eq!(
                extraction.get("status").and_then(|v| v.as_str()),
                Some("failed")
            );
            assert!(
                extraction
                    .get("error")
                    .and_then(|v| v.as_str())
                    .is_some_and(|err| err.contains("unsafe path")),
                "unexpected ZIP extraction report: {extraction:?}"
            );

            let resp = r
                .clone()
                .oneshot(
                    Request::builder()
                        .method("GET")
                        .uri(format!("/memory/assets/{asset_id}/download"))
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .expect("download retained unsafe ZIP asset");
            assert_eq!(resp.status(), StatusCode::OK);
            assert_eq!(
                resp.headers()
                    .get(axum::http::header::CONTENT_TYPE)
                    .and_then(|v| v.to_str().ok()),
                Some("application/zip")
            );
            assert_eq!(
                resp.headers()
                    .get(axum::http::header::CONTENT_DISPOSITION)
                    .and_then(|v| v.to_str().ok()),
                Some("attachment; filename=\"unsafe.zip\"")
            );
            let downloaded = resp.into_body().collect().await.unwrap().to_bytes();
            assert_eq!(downloaded.as_ref(), bytes.as_slice());

            let (status, hits) = call(
                r.clone(),
                "POST",
                "/memory/documents/search",
                Some(json!({
                    "query": "evil",
                    "limit": 5
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "search body: {hits}");
            assert_eq!(
                hits.as_array().map(Vec::len),
                Some(0),
                "unsafe ZIP should not create searchable chunks: {hits}"
            );

            asset_id
        });

        let (extractor_name, status, error): (String, String, Option<String>) = h
            .open_db()
            .query_row(
                "SELECT extractor_name, status, error FROM asset_extractions WHERE asset_id = ?1",
                rusqlite::params![asset_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("failed ZIP extraction row");
        assert_eq!(extractor_name, "zip_manifest");
        assert_eq!(status, "failed");
        assert!(
            error
                .as_deref()
                .is_some_and(|err| err.contains("unsafe path")),
            "unexpected stored ZIP extraction error: {error:?}"
        );

        drop(r);
        h.shutdown(&runtime);
    }

    #[test]
    fn document_upload_roundtrip_retains_unparsed_binary_asset() {
        let runtime = rt();
        let h = Harness::new_with_embedder(&runtime);
        let r = h.router.clone();
        let data_dir = h.registry.data_dir().to_path_buf();
        let asset_root = h._tmp.path().to_path_buf();
        let asset_id = runtime.block_on(async {
            let bytes = b"unsupported binary placeholder".to_vec();
            let (status, prepared) = call(
                r.clone(),
                "POST",
                "/memory/documents/uploads",
                Some(json!({
                    "filename": "artifact.bin",
                    "mime_type": "application/octet-stream",
                    "size_bytes": bytes.len()
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "prepare body: {prepared}");
            assert_eq!(
                prepared
                    .get("default_store_original_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            let upload_id = prepared
                .get("upload_id")
                .and_then(|v| v.as_str())
                .expect("upload_id")
                .to_string();
            let upload_url = prepared
                .get("upload_url")
                .and_then(|v| v.as_str())
                .expect("upload_url")
                .to_string();

            let req = Request::builder()
                .method("PATCH")
                .uri(upload_url)
                .header("content-type", "application/octet-stream")
                .header(crate::document_upload::UPLOAD_OFFSET_HEADER, "0")
                .header(
                    crate::document_upload::UPLOAD_LENGTH_HEADER,
                    bytes.len().to_string(),
                )
                .body(Body::from(bytes.clone()))
                .unwrap();
            let resp = r.clone().oneshot(req).await.expect("patch upload");
            assert_eq!(resp.status(), StatusCode::NO_CONTENT);
            let _ = resp.into_body().collect().await.unwrap();

            let (status, committed) = call(
                r.clone(),
                "POST",
                &format!("/memory/documents/uploads/{upload_id}/commit"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "commit body: {committed}");
            let staged_uri = committed
                .get("staged_uri")
                .and_then(|v| v.as_str())
                .expect("staged_uri")
                .to_string();
            let staged_path = crate::document_upload::staged_path_for_tests(&data_dir, &staged_uri)
                .expect("staged path");
            let staged_dir = staged_path
                .parent()
                .expect("staged file has upload dir")
                .to_path_buf();
            assert!(staged_path.is_file(), "staged file should exist");

            let (status, ingested) = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(json!({
                    "staged_uri": staged_uri
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "ingest body: {ingested}");
            assert_eq!(ingested.get("document_id"), Some(&Value::Null));
            assert_eq!(ingested.get("report"), Some(&Value::Null));
            assert_eq!(
                ingested
                    .get("stored_original_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            assert_eq!(
                ingested.get("extraction_status").and_then(|v| v.as_str()),
                Some("stored_unparsed")
            );
            assert_eq!(
                ingested.get("chunks_persisted").and_then(|v| v.as_u64()),
                Some(0)
            );
            let asset = ingested
                .get("asset")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing retained asset: {ingested}"));
            assert_eq!(
                asset.get("filename").and_then(|v| v.as_str()),
                Some("artifact.bin")
            );
            assert_eq!(
                asset.get("mime_type").and_then(|v| v.as_str()),
                Some("application/octet-stream")
            );
            assert_eq!(
                asset.get("size_bytes").and_then(|v| v.as_u64()),
                Some(bytes.len() as u64)
            );
            let asset_id = asset
                .get("asset_id")
                .and_then(|v| v.as_str())
                .expect("asset_id")
                .to_string();
            let storage_path = asset
                .get("storage_path")
                .and_then(|v| v.as_str())
                .expect("asset storage_path");
            assert!(
                asset_root.join(storage_path).is_file(),
                "persistent original file should exist in the tenant asset store"
            );
            let extraction = ingested
                .get("extraction")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing extraction report: {ingested}"));
            assert_eq!(
                extraction.get("asset_id").and_then(|v| v.as_str()),
                Some(asset_id.as_str())
            );
            assert_eq!(
                extraction.get("extractor_name").and_then(|v| v.as_str()),
                Some("fallback_binary")
            );
            assert_eq!(
                extraction.get("status").and_then(|v| v.as_str()),
                Some("stored_unparsed")
            );
            assert!(
                extraction
                    .get("error")
                    .and_then(|v| v.as_str())
                    .is_some_and(|err| err.contains("unsupported extension: bin")),
                "unexpected extraction error: {extraction:?}"
            );
            assert_eq!(
                ingested
                    .get("deleted_staged_file")
                    .and_then(|v| v.as_bool()),
                Some(true)
            );
            assert!(
                !staged_path.exists(),
                "staged source file should be deleted after asset-only ingest"
            );
            assert!(
                !staged_dir.exists(),
                "empty per-upload staging dir should be removed after asset-only ingest"
            );

            let resp = r
                .clone()
                .oneshot(
                    Request::builder()
                        .method("GET")
                        .uri(format!("/memory/assets/{asset_id}/download"))
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .expect("download retained binary asset");
            assert_eq!(resp.status(), StatusCode::OK);
            assert_eq!(
                resp.headers()
                    .get(axum::http::header::CONTENT_TYPE)
                    .and_then(|v| v.to_str().ok()),
                Some("application/octet-stream")
            );
            assert_eq!(
                resp.headers()
                    .get(axum::http::header::CONTENT_DISPOSITION)
                    .and_then(|v| v.to_str().ok()),
                Some("attachment; filename=\"artifact.bin\"")
            );
            let downloaded = resp.into_body().collect().await.unwrap().to_bytes();
            assert_eq!(downloaded.as_ref(), bytes.as_slice());
            asset_id
        });

        let (status, error): (String, Option<String>) = h
            .open_db()
            .query_row(
                "SELECT status, error FROM asset_extractions WHERE asset_id = ?1",
                rusqlite::params![asset_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("asset extraction row");
        assert_eq!(status, "stored_unparsed");
        assert!(
            error
                .as_deref()
                .is_some_and(|err| err.contains("unsupported extension: bin")),
            "unexpected stored extraction error: {error:?}"
        );

        drop(r);
        h.shutdown(&runtime);
    }

    #[test]
    fn document_upload_retained_asset_survives_document_ingest_failure() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let asset_id = runtime.block_on(async {
            let bytes = b"# Uploaded\n\nthis needs an embedder".to_vec();
            let (status, prepared) = call(
                r.clone(),
                "POST",
                "/memory/documents/uploads",
                Some(json!({
                    "filename": "needs-embedder.md",
                    "mime_type": "text/markdown",
                    "size_bytes": bytes.len()
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "prepare body: {prepared}");
            let upload_id = prepared
                .get("upload_id")
                .and_then(|v| v.as_str())
                .expect("upload_id")
                .to_string();
            let upload_url = prepared
                .get("upload_url")
                .and_then(|v| v.as_str())
                .expect("upload_url")
                .to_string();

            let req = Request::builder()
                .method("PATCH")
                .uri(upload_url)
                .header("content-type", "application/octet-stream")
                .header(crate::document_upload::UPLOAD_OFFSET_HEADER, "0")
                .header(
                    crate::document_upload::UPLOAD_LENGTH_HEADER,
                    bytes.len().to_string(),
                )
                .body(Body::from(bytes))
                .unwrap();
            let resp = r.clone().oneshot(req).await.expect("patch upload");
            assert_eq!(resp.status(), StatusCode::NO_CONTENT);
            let _ = resp.into_body().collect().await.unwrap();

            let (status, committed) = call(
                r.clone(),
                "POST",
                &format!("/memory/documents/uploads/{upload_id}/commit"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "commit body: {committed}");
            let staged_uri = committed
                .get("staged_uri")
                .and_then(|v| v.as_str())
                .expect("staged_uri")
                .to_string();

            let (status, ingested) = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(json!({
                    "staged_uri": staged_uri
                })),
            )
            .await;
            assert_eq!(
                status,
                StatusCode::OK,
                "asset-retaining ingest should return partial result: {ingested}"
            );
            assert_eq!(ingested.get("document_id"), Some(&Value::Null));
            assert_eq!(
                ingested.get("extraction_status").and_then(|v| v.as_str()),
                Some("failed")
            );
            assert!(
                ingested
                    .get("extraction_error")
                    .and_then(|v| v.as_str())
                    .is_some_and(|err| err.contains("writer has no embedder")),
                "unexpected extraction error: {ingested}"
            );
            let asset = ingested
                .get("asset")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing retained asset: {ingested}"));
            let extraction = ingested
                .get("extraction")
                .and_then(|v| v.as_object())
                .unwrap_or_else(|| panic!("missing failed extraction report: {ingested}"));
            assert_eq!(
                extraction.get("extractor_name").and_then(|v| v.as_str()),
                Some("markdown_text")
            );
            assert_eq!(
                extraction.get("status").and_then(|v| v.as_str()),
                Some("failed")
            );
            asset
                .get("asset_id")
                .and_then(|v| v.as_str())
                .expect("asset_id")
                .to_string()
        });

        let (extractor_name, status): (String, String) = h
            .open_db()
            .query_row(
                "SELECT extractor_name, status FROM asset_extractions WHERE asset_id = ?1",
                rusqlite::params![asset_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("failed extraction row");
        assert_eq!(extractor_name, "markdown_text");
        assert_eq!(status, "failed");

        drop(r);
        h.shutdown(&runtime);
    }

    #[test]
    fn asset_download_decrypts_encrypted_sidecar() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let asset_id = AssetId::new();
        let plaintext = b"encrypted retained source bytes".to_vec();
        let sha256 = hex::encode(Sha256::digest(&plaintext));
        let key = KeyMaterial::from_bytes_for_tests([0u8; 32]);
        let encrypted = solo_storage::asset_blob::encrypt_asset_blob(
            &key,
            &plaintext,
            &sha256,
            plaintext.len() as u64,
        )
        .expect("encrypt fixture asset");
        let storage_path = format!("assets/blobs/{}/{}", &sha256[..2], sha256);
        let blob_path = h.tenant_handle.snapshot_dir().join(&storage_path);
        std::fs::create_dir_all(blob_path.parent().expect("blob parent")).unwrap();
        std::fs::write(&blob_path, &encrypted.ciphertext).unwrap();

        {
            let conn = h.open_db();
            let now_ms = chrono::Utc::now().timestamp_millis();
            conn.execute(
                "INSERT INTO assets (
                    asset_id, sha256, mime_type, filename, size_bytes,
                    storage_path, source, status, created_by_principal,
                    created_at_ms, updated_at_ms, encryption_alg,
                    encryption_nonce, encrypted_size_bytes
                 ) VALUES (?1, ?2, 'text/plain', 'source.txt', ?3,
                    ?4, 'test://encrypted', 'active', 'tester',
                    ?5, ?5, 'xchacha20poly1305-blake3-v1', ?6, ?7)",
                rusqlite::params![
                    asset_id.to_string(),
                    &sha256,
                    plaintext.len() as i64,
                    &storage_path,
                    now_ms,
                    encrypted.nonce,
                    encrypted.ciphertext.len() as i64,
                ],
            )
            .expect("insert encrypted asset");
        }

        runtime.block_on(async {
            let resp = r
                .oneshot(
                    Request::builder()
                        .method("GET")
                        .uri(format!("/memory/assets/{asset_id}/download"))
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .expect("download encrypted asset");
            assert_eq!(resp.status(), StatusCode::OK);
            let downloaded = resp.into_body().collect().await.unwrap().to_bytes();
            assert_eq!(downloaded.as_ref(), plaintext.as_slice());
        });

        h.shutdown(&runtime);
    }

