    #[test]
    fn staged_ingest_respects_upload_lifecycle_lock_barrier() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let data_dir = h.registry.data_dir().to_path_buf();
        runtime.block_on(async {
            let bytes = b"ingest lifecycle barrier".to_vec();
            let (status, prepared) = call(
                r.clone(),
                "POST",
                "/memory/documents/uploads",
                Some(json!({
                    "filename": "ingest-barrier.md",
                    "mime_type": "text/markdown",
                    "size_bytes": bytes.len()
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "prepare body: {prepared}");
            let upload_id = prepared["upload_id"].as_str().unwrap().to_string();
            let upload_url = prepared["upload_url"].as_str().unwrap().to_string();

            let req = Request::builder()
                .method("PATCH")
                .uri(upload_url)
                .header("content-type", "application/octet-stream")
                .header(crate::document_upload::UPLOAD_OFFSET_HEADER, "0")
                .header(
                    crate::document_upload::UPLOAD_LENGTH_HEADER,
                    bytes.len().to_string(),
                )
                .body(Body::from(bytes))
                .unwrap();
            let response = r.clone().oneshot(req).await.expect("patch upload");
            assert_eq!(response.status(), StatusCode::NO_CONTENT);

            let (status, committed) = call(
                r.clone(),
                "POST",
                &format!("/memory/documents/uploads/{upload_id}/commit"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "commit body: {committed}");
            let staged_uri = committed["staged_uri"].as_str().unwrap().to_string();
            let lock_path =
                crate::document_upload::upload_lock_path_for_tests(&data_dir, &upload_id).unwrap();
            let barrier = crate::document_upload::acquire_upload_lock_for_tests(
                &data_dir, &upload_id, "ingest",
            )
            .expect("ingest barrier lock");

            let (status, busy) = call(
                r.clone(),
                "GET",
                &format!("/memory/documents/uploads/{upload_id}"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "busy status body: {busy}");
            assert_eq!(busy["status"], "busy");
            assert_eq!(busy["operation_in_progress"], true);
            assert_eq!(busy["active_operation"], "ingest");
            assert_eq!(busy["terminal"], false);

            let (status, body) = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(json!({ "staged_uri": staged_uri.clone() })),
            )
            .await;
            assert_eq!(status, StatusCode::CONFLICT, "ingest body: {body}");
            assert!(
                body["error"]
                    .as_str()
                    .is_some_and(|error| error.contains("upload is busy"))
            );
            assert!(lock_path.exists());

            drop(barrier);
            let (status, body) = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(json!({ "staged_uri": staged_uri })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "ingest body: {body}");
            assert!(
                lock_path.exists(),
                "ingest cleanup must preserve the reusable lock path"
            );
            assert_eq!(body["idempotent_replay"], false);
            assert!(body["ingest_completed_at_ms"].as_i64().unwrap() > 0);

            let (status, terminal) = call(
                r.clone(),
                "GET",
                &format!("/memory/documents/uploads/{upload_id}"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "terminal status: {terminal}");
            assert_eq!(terminal["status"], "ingested");
            assert_eq!(terminal["terminal"], true);
            assert_eq!(terminal["operation_in_progress"], false);
            assert_eq!(
                terminal["ingest_result"]["document_id"],
                body["document_id"]
            );
        });
        drop(r);
        h.shutdown(&runtime);
    }

    #[test]
    fn commit_and_ingest_recover_from_lost_and_concurrent_responses() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let data_dir = h.registry.data_dir().to_path_buf();
        runtime.block_on(async {
            let marker = format!("idempotent-ingest-{}", uuid::Uuid::now_v7());
            let bytes = format!("# Durable upload receipt\n\n{marker}\n").into_bytes();
            let (status, prepared) = call(
                r.clone(),
                "POST",
                "/memory/documents/uploads",
                Some(json!({
                    "filename": "idempotent.md",
                    "mime_type": "text/markdown",
                    "size_bytes": bytes.len()
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "prepare body: {prepared}");
            let upload_id = prepared["upload_id"].as_str().unwrap().to_string();
            let upload_url = prepared["upload_url"].as_str().unwrap().to_string();

            let request = Request::builder()
                .method("PATCH")
                .uri(upload_url)
                .header("content-type", "application/octet-stream")
                .header(crate::document_upload::UPLOAD_OFFSET_HEADER, "0")
                .header(
                    crate::document_upload::UPLOAD_LENGTH_HEADER,
                    bytes.len().to_string(),
                )
                .body(Body::from(bytes))
                .unwrap();
            let response = r.clone().oneshot(request).await.expect("patch upload");
            assert_eq!(response.status(), StatusCode::NO_CONTENT);

            let commit_path = format!("/memory/documents/uploads/{upload_id}/commit");
            let (status, first_commit) = call(r.clone(), "POST", &commit_path, None).await;
            assert_eq!(status, StatusCode::OK, "first commit: {first_commit}");
            // Treat the first body as if transport delivery was lost. Retrying
            // must reconstruct the same response from stable manifest state.
            let (status, replayed_commit) = call(r.clone(), "POST", &commit_path, None).await;
            assert_eq!(status, StatusCode::OK, "replayed commit: {replayed_commit}");
            assert_eq!(replayed_commit, first_commit);
            let staged_uri = first_commit["staged_uri"].as_str().unwrap().to_string();
            let ingest_body = json!({
                "staged_uri": staged_uri,
                "retain_source_file": false,
                "store_original_file": true
            });

            let first_ingest = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(ingest_body.clone()),
            );
            let concurrent_ingest = call(
                r.clone(),
                "POST",
                "/memory/documents/staged/ingest",
                Some(ingest_body.clone()),
            );
            let (first, second) = tokio::join!(first_ingest, concurrent_ingest);

            let mut successful = Vec::new();
            for (response_status, body) in [first, second] {
                match response_status {
                    StatusCode::OK => successful.push(body),
                    StatusCode::CONFLICT => assert!(
                        body["error"]
                            .as_str()
                            .is_some_and(|error| error.contains("upload is busy")),
                        "unexpected concurrent conflict: {body}"
                    ),
                    other => panic!("unexpected concurrent ingest status {other}: {body}"),
                }
            }
            if successful.len() == 1 {
                let (status, replay) = call(
                    r.clone(),
                    "POST",
                    "/memory/documents/staged/ingest",
                    Some(ingest_body.clone()),
                )
                .await;
                assert_eq!(status, StatusCode::OK, "lost-response replay: {replay}");
                successful.push(replay);
            }
            assert_eq!(successful.len(), 2);
            assert_eq!(
                successful
                    .iter()
                    .filter(|body| body["idempotent_replay"] == false)
                    .count(),
                1,
                "exactly one request may perform the ingest"
            );
            assert_eq!(
                successful
                    .iter()
                    .filter(|body| body["idempotent_replay"] == true)
                    .count(),
                1,
                "the other request must replay the durable receipt"
            );
            assert_eq!(successful[0]["document_id"], successful[1]["document_id"]);
            assert_eq!(successful[0]["asset"], successful[1]["asset"]);
            assert!(
                !data_dir
                    .join("staged-documents")
                    .join(&upload_id)
                    .join("idempotent.md")
                    .exists()
            );

            let (status, upload_status) = call(
                r.clone(),
                "GET",
                &format!("/memory/documents/uploads/{upload_id}"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::OK, "terminal status: {upload_status}");
            assert_eq!(upload_status["status"], "ingested");
            assert_eq!(upload_status["terminal"], true);
            assert_eq!(
                upload_status["ingest_result"]["document_id"],
                successful[0]["document_id"]
            );

            let (status, abort_body) = call(
                r.clone(),
                "DELETE",
                &format!("/memory/documents/uploads/{upload_id}"),
                None,
            )
            .await;
            assert_eq!(status, StatusCode::CONFLICT, "abort body: {abort_body}");
        });
        drop(r);
        h.shutdown(&runtime);
    }

