    #[test]
    fn import_documents_endpoint_dry_run_caps_after_stable_sort() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let dir = h._tmp.path().join("ordered-docs");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("z.md"), "# Z\nbody").unwrap();
        std::fs::write(dir.join("a.md"), "# A\nbody").unwrap();
        std::fs::write(dir.join("m.md"), "# M\nbody").unwrap();

        let r = h.router.clone();
        let (status, body) = runtime.block_on(call(
            r,
            "POST",
            "/memory/documents/import",
            Some(json!({
                "path": dir.display().to_string(),
                "dry_run": true,
                "max_files": 2
            })),
        ));
        assert_eq!(status, StatusCode::OK);
        let paths = body
            .get("files")
            .and_then(|v| v.as_array())
            .expect("files")
            .iter()
            .map(|file| {
                file.get("path")
                    .and_then(|v| v.as_str())
                    .expect("path")
                    .to_string()
            })
            .collect::<Vec<_>>();
        assert_eq!(paths.len(), 2, "expected capped files, got {body}");
        assert!(
            paths[0].ends_with("a.md"),
            "expected first sorted path, got {paths:?}"
        );
        assert!(
            paths[1].ends_with("m.md"),
            "expected second sorted path, got {paths:?}"
        );
        assert_eq!(body.get("truncated").and_then(|v| v.as_bool()), Some(true));
        h.shutdown(&runtime);
    }

