    #[test]
    fn edges_filter_by_node_id_finds_incident_edges() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let memory_id = "33330000-0000-7000-8000-000000000001";
        {
            let conn = h.open_db();
            let rowid = seed_episode(&conn, memory_id, 100, "ep multi-triple");
            seed_triple_row(&conn, "t-a", "Alice", "p", "Bob", Some(rowid));
            seed_triple_row(&conn, "t-b", "Alice", "p", "Carol", Some(rowid));
            seed_triple_row(&conn, "t-c", "Alice", "p", "Dave", Some(rowid));
            // Decoy episode with its own triple — must NOT come back.
            let decoy_rowid =
                seed_episode(&conn, "33330000-0000-7000-8000-000000000999", 200, "decoy");
            seed_triple_row(&conn, "t-decoy", "Alice", "p", "Eve", Some(decoy_rowid));
        }
        let uri = format!(
            "/v1/graph/edges?type=triple&node_id={}",
            percent_encode_node_id(&format!("ep:{memory_id}"))
        );
        let (status, body) = runtime.block_on(call(h.router.clone(), "GET", &uri, None));
        assert_eq!(status, StatusCode::OK, "body: {body}");
        let edges = body["edges"].as_array().unwrap();
        assert_eq!(edges.len(), 3, "expected 3 incident edges: {body}");
        let mut targets = std::collections::HashSet::new();
        for e in edges {
            assert_eq!(e["kind"], "triple", "{body}");
            assert_eq!(e["source"], "ent:Alice", "{body}");
            assert_eq!(e["predicate"], "p", "{body}");
            targets.insert(e["target"].as_str().unwrap_or_default().to_string());
        }
        let expected_targets: std::collections::HashSet<String> =
            ["ent:Bob", "ent:Carol", "ent:Dave"]
                .into_iter()
                .map(str::to_string)
                .collect();
        assert_eq!(targets, expected_targets, "{body}");
        h.shutdown(&runtime);
    }

