    #[test]
    fn edges_triple_catalog_prefers_relationship_edges_with_metadata() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let memory_id = "44440000-0000-7000-8000-000000000202";
        {
            let conn = h.open_db();
            let rowid = seed_episode(&conn, memory_id, 100, "Solo uses Ollama");
            seed_triple_row(&conn, "t-rel-edge", "Solo", "uses", "Ollama", Some(rowid));
            seed_relationship_edge_for_triple(
                &conn,
                "edge-solo-ollama",
                "t-rel-edge",
                "Solo",
                "uses",
                "Ollama",
                rowid,
                memory_id,
            );
        }

        let (status, body) = runtime.block_on(call(
            h.router.clone(),
            "GET",
            "/v1/graph/edges?type=triple&node_id=ent:Solo",
            None,
        ));
        assert_eq!(status, StatusCode::OK, "{body}");
        let edges = body["edges"].as_array().unwrap();
        assert_eq!(
            edges.len(),
            1,
            "relationship edge should suppress legacy fallback duplicate: {body}"
        );
        let edge = &edges[0];
        assert_eq!(edge["source"], "ent:Solo");
        assert_eq!(edge["target"], "ent:Ollama");
        assert_eq!(edge["predicate"], "uses");
        let weight = edge["weight"].as_f64().expect("edge weight");
        assert!(
            (weight - 0.88).abs() < 0.000_001,
            "edge weight should preserve relationship confidence: {edge}"
        );
        let meta = edge["meta"].as_object().expect("relationship edge meta");
        assert_eq!(meta["relationship_edge_id"], "edge-solo-ollama");
        assert_eq!(meta["subject_entity_id"], "Solo");
        assert_eq!(meta["object_entity_id"], "Ollama");
        assert_eq!(meta["object_kind"], "entity");
        let confidence = meta["confidence"].as_f64().expect("meta confidence");
        assert!(
            (confidence - 0.88).abs() < 0.000_001,
            "meta confidence should preserve relationship confidence: {edge}"
        );
        let strength = meta["strength"].as_f64().expect("meta strength");
        assert!(
            (strength - 0.77).abs() < 0.000_001,
            "meta strength should preserve relationship strength: {edge}"
        );
        assert_eq!(meta["evidence_count"], 1);
        assert_eq!(meta["valid_from_ms"], 123);
        assert_eq!(meta["valid_to_ms"], 456);
        assert_eq!(meta["status"], "active");
        assert_eq!(meta["evidence_memory_id"], memory_id);
        h.shutdown(&runtime);
    }

