    #[test]
    fn paths_returns_direct_and_two_hop_relationship_paths() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let memory_id = "44440000-0000-7000-8000-000000000401";
        {
            let conn = h.open_db();
            let rowid = seed_episode(
                &conn,
                memory_id,
                100,
                "Solo connects to Relay through Graphiti",
            );
            seed_triple_row(&conn, "t-path-direct", "Solo", "uses", "Relay", Some(rowid));
            seed_relationship_edge_for_triple(
                &conn,
                "edge-path-direct",
                "t-path-direct",
                "Solo",
                "uses",
                "Relay",
                rowid,
                memory_id,
            );
            seed_triple_row(
                &conn,
                "t-path-first",
                "Solo",
                "models",
                "Graphiti",
                Some(rowid),
            );
            seed_relationship_edge_for_triple(
                &conn,
                "edge-path-first",
                "t-path-first",
                "Solo",
                "models",
                "Graphiti",
                rowid,
                memory_id,
            );
            seed_triple_row(
                &conn,
                "t-path-second",
                "Graphiti",
                "informs",
                "Relay",
                Some(rowid),
            );
            seed_relationship_edge_for_triple(
                &conn,
                "edge-path-second",
                "t-path-second",
                "Graphiti",
                "informs",
                "Relay",
                rowid,
                memory_id,
            );
        }

        let (status, body) = runtime.block_on(call(
            h.router.clone(),
            "GET",
            "/v1/graph/paths?from=ent:Solo&to=ent:Relay&max_hops=2",
            None,
        ));
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["from"], "ent:Solo");
        assert_eq!(body["to"], "ent:Relay");
        assert_eq!(body["max_hops"], 2);
        let paths = body["paths"].as_array().expect("paths array");
        assert_eq!(paths.len(), 2, "{body}");

        let direct = paths
            .iter()
            .find(|path| path["hops"] == 1)
            .unwrap_or_else(|| panic!("direct path missing: {body}"));
        assert_eq!(direct["nodes"], json!(["ent:Solo", "ent:Relay"]));
        assert_eq!(direct["edges"][0]["edge_id"], "edge-path-direct");
        assert_eq!(direct["edges"][0]["predicate"], "uses");
        assert_eq!(direct["edges"][0]["evidence_memory_id"], memory_id);
        assert!(
            direct["reason_codes"]
                .as_array()
                .unwrap()
                .iter()
                .any(|code| code == "direct_relationship"),
            "{body}"
        );

        let two_hop = paths
            .iter()
            .find(|path| path["hops"] == 2)
            .unwrap_or_else(|| panic!("two-hop path missing: {body}"));
        assert_eq!(
            two_hop["nodes"],
            json!(["ent:Solo", "ent:Graphiti", "ent:Relay"])
        );
        assert_eq!(two_hop["edges"][0]["edge_id"], "edge-path-first");
        assert_eq!(two_hop["edges"][1]["edge_id"], "edge-path-second");
        assert!(
            two_hop["reason_codes"]
                .as_array()
                .unwrap()
                .iter()
                .any(|code| code == "two_hop_relationship_path"),
            "{body}"
        );
        h.shutdown(&runtime);
    }

