    #[test]
    fn status_embedder_runtime_uses_embedder_probe_url() {
        use solo_core::{Embedder, Embedding, EmbeddingDtype};
        use wiremock::matchers::{method, path};
        use wiremock::{Mock, MockServer, ResponseTemplate};

        struct ProbeEmbedder {
            probe_url: String,
        }

        #[async_trait::async_trait]
        impl Embedder for ProbeEmbedder {
            fn name(&self) -> &str {
                "ollama:custom-embed"
            }

            fn version(&self) -> &str {
                "v1"
            }

            fn dim(&self) -> usize {
                4
            }

            fn dtype(&self) -> EmbeddingDtype {
                EmbeddingDtype::F32
            }

            fn runtime_probe_url(&self) -> Option<String> {
                Some(self.probe_url.clone())
            }

            async fn embed_batch(&self, _texts: &[&str]) -> solo_core::Result<Vec<Embedding>> {
                panic!("status runtime must not call embed_batch")
            }
        }

        let runtime = rt();
        runtime.block_on(async {
            let server = MockServer::start().await;
            Mock::given(method("GET"))
                .and(path("/custom-tags"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({ "models": [] })))
                .expect(1)
                .mount(&server)
                .await;

            let embedder = ProbeEmbedder {
                probe_url: format!("{}/custom-tags", server.uri()),
            };
            let status = status_embedder_runtime(&embedder).await;
            assert!(status.running);
            assert_eq!(status.status, "ready");
            assert!(status.detail.contains("without loading"));
        });
    }

