    #[test]
    fn switch_steward_cadence_updates_config_and_returns_restart_plan() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let config_path = h._tmp.path().join("solo.config.toml");
        runtime.block_on(async {
            let (status, body) = call(
                r,
                "POST",
                "/v1/settings/steward/cadence",
                Some(json!({
                    "trigger_interval_secs": 900,
                    "trigger_episode_count": 25,
                    "consolidate_interval_secs": 1800,
                    "cluster_timeout_secs": 45
                })),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "body: {body}");
            assert_eq!(body["changed"].as_bool(), Some(true));
            assert_eq!(body["restart_required"].as_bool(), Some(true));
            assert_eq!(
                body.pointer("/next/trigger_interval_secs")
                    .and_then(|v| v.as_u64()),
                Some(900)
            );
            assert_eq!(
                body.pointer("/next/trigger_episode_count")
                    .and_then(|v| v.as_u64()),
                Some(25)
            );
            assert_eq!(
                body.pointer("/next/consolidate_interval_secs")
                    .and_then(|v| v.as_u64()),
                Some(1800)
            );
            assert_eq!(
                body.pointer("/next/cluster_timeout_secs")
                    .and_then(|v| v.as_u64()),
                Some(45)
            );
        });

        let cfg = SoloConfig::read(&config_path).expect("read switched config");
        assert_eq!(cfg.triples.trigger_interval_secs, 900);
        assert_eq!(cfg.triples.trigger_episode_count, 25);
        assert_eq!(cfg.triples.consolidate_interval_secs, 1800);
        assert_eq!(cfg.triples.cluster_timeout_secs, 45);
        h.shutdown(&runtime);
    }

