    #[test]
    fn logs_tails_and_redacts_tray_log() {
        let runtime = rt();
        let h = Harness::new(&runtime);
        let r = h.router.clone();
        let path = h._tmp.path().join("tray.log");
        std::fs::write(
            &path,
            "INFO boot\nWARN token=secret-token\n\x1B[31mERROR\x1B[0m bearer abc123\n",
        )
        .expect("write tray log");

        runtime.block_on(async {
            let (status, body) = call(r, "GET", "/v1/logs?limit=2", None).await;
            assert_eq!(status, StatusCode::OK, "body: {body}");
            assert_eq!(body["exists"].as_bool(), Some(true));
            assert_eq!(body["limit"].as_u64(), Some(2));
            assert!(
                body["size_bytes"].as_u64().is_some_and(|bytes| bytes > 0),
                "expected size_bytes in {body}"
            );
            assert!(
                body["modified_at_ms"].as_i64().is_some(),
                "expected modified_at_ms in {body}"
            );

            let lines = body["lines"].as_array().expect("lines array");
            assert_eq!(lines.len(), 2, "body: {body}");
            assert_eq!(lines[0]["level"].as_str(), Some("warn"));
            assert_eq!(lines[1]["level"].as_str(), Some("error"));

            let rendered = serde_json::to_string(lines).unwrap();
            assert!(
                !rendered.contains("secret-token"),
                "secret leaked: {rendered}"
            );
            assert!(!rendered.contains("abc123"), "bearer leaked: {rendered}");
            assert!(rendered.contains("[redacted]"));
        });
        h.shutdown(&runtime);
    }

